UPDATE public.guides SET content = $CTA$# Fonctionnalités LlamaKusi 2026 : Parcours, Coach IA, Examens Blancs et Livret du Citoyen

Vous vous demandez précisément ce que propose LlamaKusi avant de vous lancer ? Voici la liste complète de nos fonctionnalités, pour le TEF IRN comme pour l'examen civique.

## Est-ce que LlamaKusi propose des parcours thématiques organisés par niveau ?

Oui, LlamaKusi propose [16 parcours thématiques](https://llamakusi.com/tef-irn/parcours), chacun combinant un niveau CECRL (A1, A2, B1 ou B2) et une catégorie linguistique (Conjugaison, Vocabulaire, Syntaxe ou Grammaire).

Chaque parcours regroupe environ [6 leçons](https://llamakusi.com/tef-irn/lessons) suivies d'exercices, pensées pour progresser pas à pas sur une compétence précise plutôt que de réviser au hasard. Un candidat de niveau A2 qui a besoin de renforcer sa conjugaison suit ainsi un parcours dédié, distinct de celui d'un candidat B1 qui travaille l'argumentation.

> Choisissez d'abord le parcours correspondant à votre niveau réel plutôt qu'au niveau visé : les fondations comptent plus que la vitesse au départ.

## Quels types d'exercices propose LlamaKusi pour s'entraîner ?

Chaque leçon est suivie d'un quiz puis de **3 types d'exercices complémentaires** : la Chasse aux erreurs, l'Entraînement QCM et l'Entraînement Vocabulaire.

La Chasse aux erreurs demande de cliquer directement sur l'erreur dans une phrase, si elle existe, ce qui entraîne un réflexe de détection utile pour l'épreuve de compréhension écrite. L'Entraînement QCM couvre la validation des règles grammaticales et syntaxiques. L'Entraînement Vocabulaire s'appuie sur un système de répétition espacée qui recalcule le moment où un mot risque d'être oublié, pour le représenter au bon moment plutôt que de façon aléatoire.

> Alternez les 3 types d'exercices dans une même session plutôt que de vous concentrer sur un seul : la variété consolide mieux les automatismes.

## Comment fonctionne le Coach IA Expression Écrite de LlamaKusi ?

Le [Coach IA Expression Écrite](https://llamakusi.com/tef-irn/guides/coach-ia-expression-ecrite-tef-irn) analyse votre production sur des sujets similaires à ceux de l'examen et vous renvoie une **note estimée avec des conseils de reformulation**, en quelques secondes.

L'analyse porte sur la grammaire, la syntaxe et le vocabulaire, les trois critères également évalués par les correcteurs du TEF IRN. Ce retour rapide permet de corriger un texte puis d'en retenter une version améliorée dans la même session, plutôt que d'attendre plusieurs jours un retour de formateur.

> Réécrivez toujours une version corrigée après le retour de l'IA : lire la correction sans la retravailler limite fortement la progression.

## Comment fonctionne le Coach IA Expression Orale de LlamaKusi ?

Le [Coach IA Expression Orale](https://llamakusi.com/tef-irn/guides/coach-ia-expression-orale-tef-irn) analyse votre **prononciation et votre fluidité** sur tous les thèmes de l'examen, sans jugement et à volonté.

Vous répondez à voix haute à un sujet type TEF IRN, et l'IA restitue une évaluation détaillée plutôt qu'une note brute peu actionnable. Cette disponibilité permanente aide en particulier les candidats les plus anxieux à l'oral, qui peuvent répéter un même exercice autant de fois que nécessaire avant de se sentir prêts.

> Entraînez-vous dans un environnement calme : un bruit de fond parasite peut fausser l'analyse de votre prononciation.

## Est-ce que LlamaKusi propose un examen blanc TEF IRN en conditions réelles ?

Oui, l'[examen blanc LlamaKusi](https://llamakusi.com/tef-irn/guides/examen-blanc-tef-irn-en-ligne) reproduit les **4 épreuves chronométrées** du TEF IRN, enchaînées sans interruption comme le jour J.

Il ne s'agit pas d'un simple quiz mais d'une répétition générale complète : compréhension orale, compréhension écrite, expression écrite et expression orale s'enchaînent dans les mêmes conditions de temps qu'en centre agréé. Un rapport détaillé identifie ensuite la compétence la plus fragile, pour orienter les révisions suivantes.

> Passez votre premier examen blanc tôt dans votre préparation : il doit servir de diagnostic, pas de simple contrôle final.

## Qu'est-ce que le Livret du Citoyen sur LlamaKusi ?

[Le Livret du Citoyen](https://llamakusi.com/examen-civique/livret) est le point d'entrée pour préparer à la fois l'[examen civique](https://llamakusi.com/examen-civique/examen-blanc)  et l'entretien de naturalisation, à commencer le plus tôt possible dans votre démarche.

Il reprend les 5 thématiques officielles de l'examen civique (principes et valeurs de la République, système institutionnel et politique, droits et devoirs, histoire-géographie-culture, vie dans la société française), pour une entrée en matière progressive avant de passer à l'entraînement ciblé.

> Commencez le Livret du Citoyen bien avant votre inscription à l'examen : le contenu est aussi utile pour l'entretien de naturalisation que pour le QCM lui-même.

## Comment savoir si je suis éligible ou dispensé de l'examen civique sur LlamaKusi ?

La page [Éligibilité](https://llamakusi.com/examen-civique/eligibilite) de LlamaKusi vous aide à identifier votre situation exacte : quelle démarche vous concerne, et si une dispense s'applique à votre cas.

L'examen civique existe en 3 versions selon la démarche (carte de séjour pluriannuelle, carte de résident, naturalisation), avec des règles de dispense propres à chacune (âge, situation de santé, statut de protection internationale, certains accords bilatéraux). Vérifier sa situation avant de commencer à réviser évite de se préparer inutilement à un format qui ne correspond pas à sa démarche.

> Vérifiez votre éligibilité avant même de commencer à réviser : cela évite de se tromper de version d'examen dès le départ.

## Peut-on parcourir toutes les questions de l'examen civique sur LlamaKusi ?

Oui, la fonctionnalité [Parcourir](https://llamakusi.com/examen-civique/parcourir) permet d'explorer l'ensemble des questions de connaissance organisées par thématique, pour une révision structurée plutôt que hasardeuse.

Cette exploration thématique complète l'entraînement chronométré : elle permet de repérer à l'avance les sujets les moins maîtrisés avant de les retravailler en profondeur, plutôt que de découvrir ses lacunes uniquement pendant un test minuté.

> Parcourez d'abord une thématique entière avant de passer à l'entraînement chronométré : la vue d'ensemble facilite la mémorisation ensuite.

## Comment fonctionne l'entraînement et la mémorisation pour l'examen civique ?

La fonctionnalité [Entraînement & Mémorisation](https://llamakusi.com/examen-civique/entrainement) cible spécifiquement les thématiques où vos réponses sont les plus fragiles, pour concentrer l'effort là où il compte.

Plutôt que de réviser les 5 thématiques à parts égales, cet entraînement identifie vos lacunes réelles et les représente à intervalles réguliers, jusqu'à ce que la réponse soit mémorisée durablement plutôt qu'apprise par cœur à court terme.

> Ne révisez jamais les 5 thématiques à parts égales : concentrez d'abord vos efforts sur celles où votre score reste le plus bas.

## Est-ce que LlamaKusi propose un examen blanc pour l'examen civique ?

Oui, l'[examen blanc civique](https://llamakusi.com/examen-civique/guides/examen-blanc-trouver-centre-examen-civique) reproduit le **format officiel exact** : un QCM chronométré, dans les mêmes conditions que le jour J.

Cette simulation permet d'évaluer précisément où vous en êtes avant de vous présenter réellement, avec un rapport détaillé par thématique à la fin de chaque session. C'est la meilleure façon de vérifier qu'une thématique faible identifiée en amont est vraiment devenue un point fort.

> Refaites un examen blanc civique après chaque session de révision ciblée, pas seulement une fois avant l'examen réel.

## Peut-on trouver le centre d'examen civique le plus proche via LlamaKusi ?

Oui, LlamaKusi vous aide à identifier un [centre d'examen civique agréé](https://llamakusi.com/examen-civique/guides/examen-blanc-trouver-centre-examen-civique) proche de chez vous, parmi les réseaux de la CCI Paris Île-de-France et de France Éducation International.

Le choix du centre reste libre, sans obligation de passer l'examen dans son département de résidence : comparer les deux réseaux permet souvent de trouver une date plus proche ou un centre plus accessible que le premier trouvé.

> Comparez toujours les deux réseaux avant de réserver : un centre plus proche ou une date plus rapprochée existe parfois chez l'opérateur que vous n'avez pas consulté en premier.

## Comment LlamaKusi vous aide

Chez LlamaKusi, l'objectif est simple : rassembler en un seul endroit tout ce qu'il faut pour préparer sa démarche administrative sans jongler entre plusieurs outils. Testez dès maintenant le [Coach IA Oral](/tef_irn/oral), inclus dans votre abonnement, ou explorez [l'espace Examen Civique](/examen-civique), entièrement gratuit et sans inscription. Pour un accompagnement complet sur le TEF IRN incluant la correction détaillée de chaque production, découvrez les [offres Premium LlamaKusi](/tef_irn/pricing). Si vous hésitez encore entre plusieurs approches, notre [comparatif entre coaching IA et formation classique](https://llamakusi.com/tef-irn/guides/ia-vs-formation-classique-tef-irn) vous aide à trancher selon votre budget et votre emploi du temps.

## Pour aller plus loin selon votre situation

