## FAQ

**LlamaKusi couvre-t-il à la fois le TEF IRN et l'examen civique ?**
Oui, les deux démarches sont accessibles sur la même plateforme, avec des fonctionnalités dédiées à chacune.

**Toutes les fonctionnalités de l'examen civique sont-elles gratuites ?**
Oui, l'entraînement, la révision adaptative et les examens blancs de l'examen civique sont gratuits et sans inscription.

