**LlamaKusi est-il éligible au CPF ?**
Le TEF IRN sur LlamaKusi est en cours d'éligibilité au CPF ; vérifiez la page Premium pour l'état d'avancement le plus récent.

**Peut-on utiliser LlamaKusi uniquement pour l'oral ou uniquement pour l'écrit ?**
