UPDATE public.guides SET content = $CTA$# Dates Clés TEF IRN 2026 : Inscription, Convocation et Validité

Vous craignez de rater la date limite de votre dossier de naturalisation à cause du TEF IRN. En anticipant inscription, convocation et validité de 2 ans, vous gardez le contrôle sur votre calendrier.

## Quel délai minimum respecter pour s'inscrire au TEF IRN ?

Comptez généralement entre **1 et 4 semaines** avant la date de session, selon le centre choisi.

Chaque centre agréé par la CCI Paris Île-de-France fixe sa propre date limite d'inscription. Certains centres ferment les inscriptions une semaine avant l'examen, d'autres demandent jusqu'à un mois si vous passez par le CPF. Un **délai obligatoire de 20 jours** s'impose aussi entre deux inscriptions au même test, utile à savoir si vous devez repasser l'épreuve.

Exemple : un candidat qui vise une session le 15 du mois doit généralement finaliser son inscription avant le 8, sous réserve de places disponibles dans son centre.

> Réservez votre session dès que vous connaissez votre date limite de dossier, même si vous ne sentez pas encore prêt : vous pourrez toujours vous préparer intensément d'ici l'examen.

## Combien de temps avant ma date limite de dossier dois-je passer le TEF IRN ?

Passez le test **2 à 3 mois** avant le dépôt prévu de votre dossier, pour absorber les délais de résultats et un éventuel repassage.

L'instruction d'un dossier de naturalisation dure en moyenne **18 à 36 mois** après le dépôt ([service-public.fr](https://www.service-public.gouv.fr/particuliers/vosdroits/F2213) fixe un délai maximal de 18 mois pour l'administration à compter du récépissé), mais c'est la date de dépôt qui compte pour la validité du TEF IRN, pas la date d'instruction. Prévoyez aussi le délai de résultat (1 à 2 semaines) et, en cas d'échec, **20 jours minimum** avant de retenter votre chance. Pour construire l'ensemble de votre calendrier de dossier, notre [guide complet sur la naturalisation française](https://llamakusi.com/tef-irn/guides/preparer-naturalisation-francaise-2026) détaille chaque étape après le test.

Exemple : une candidate qui prévoit de déposer son dossier en septembre a intérêt à passer le TEF IRN dès juin, pour garder une marge en cas de résultat insuffisant.

> Notez la date de dépôt visée dans votre agenda, puis comptez à rebours : test, résultats, marge de sécurité.

## Quelle est la durée de validité de l'attestation TEF IRN ?

Votre attestation TEF IRN est valable **2 ans** à compter de la date de passation.

Cette validité s'apprécie au moment du dépôt de votre dossier en préfecture ou à la SDANF, pas à la date où le dossier est ensuite instruit. Passer le test trop tôt fait courir le risque qu'il expire avant le dépôt effectif ; le passer trop tard retarde tout votre calendrier. Depuis le **1er janvier 2026**, le niveau **B2** est exigé pour la naturalisation, contre B1 auparavant ([service-public.fr](https://www.service-public.gouv.fr/particuliers/vosdroits/F11926)) : vérifiez que votre score correspond bien à cette nouvelle exigence avant de considérer votre attestation valable pour votre démarche.

Exemple : un candidat titulaire d'un TEF IRN B1 obtenu en 2024 doit vérifier auprès de sa préfecture si ce niveau reste accepté pour son dossier déposé en 2026.

> Gardez une copie numérique et papier de votre attestation dès sa réception : elle vous sera redemandée à plusieurs étapes du dossier.

## Combien de temps pour recevoir convocation et résultats ?

La convocation arrive par email **1 à 3 jours** avant l'examen ; les résultats suivent sous **1 à 2 semaines**.

Le centre vous envoie la convocation par courriel avec l'adresse, l'horaire et les pièces à apporter. Si vous ne la recevez pas quelques jours avant l'examen, vérifiez vos courriers indésirables avant de contacter le centre. L'attestation officielle, elle, est délivrée par la CCI Paris Île-de-France après le délai de correction, un peu plus long pour l'expression écrite et orale que pour les épreuves de compréhension.

Exemple : « Bonjour, je n'ai pas reçu ma convocation, l'examen est dans deux jours » — un message que les centres reçoivent souvent, alors qu'elle se trouvait dans les spams.

> Ajoutez l'adresse email de votre centre à vos contacts dès l'inscription, pour éviter que la convocation atterrisse dans vos spams.

## Que faire si je rate le délai d'inscription ou ma date limite de dossier ?

Réinscrivez-vous à la prochaine session disponible et, si votre date limite de dossier est déjà dépassée, contactez votre préfecture pour connaître les options de report.

Rater une session n'est pas rédhibitoire : les centres organisent des sessions régulières, parfois hebdomadaires. En revanche, un dossier préfecture incomplet à la date limite peut être classé sans suite. Notre [guide sur l'échec au TEF IRN](https://llamakusi.com/tef-irn/guides/que-faire-si-je-rate-tef-irn) détaille les solutions concrètes si vous n'obtenez pas le niveau requis à temps.

Exemple : un candidat ayant raté sa session de mars se réinscrit immédiatement pour avril, tout en informant sa préfecture du délai supplémentaire nécessaire.

> En cas de doute sur votre date limite exacte, demandez une confirmation écrite à votre préfecture plutôt que de vous fier à une estimation.

## Combien coûte l'inscription et comment s'inscrire concrètement ?

Comptez entre **160€ et 200€** selon le centre, en inscription en ligne par carte bancaire ou sur place en espèces.

Le tarif varie selon le jour choisi (souvent plus élevé le samedi) et selon que le centre propose ou non un accompagnement CPF. L'inscription en ligne se fait sur le site du centre agréé : vous choisissez une session, réglez les frais, puis recevez votre convocation. Une inscription est généralement ferme et définitive : les frais restent acquis même en cas d'annulation, sauf justificatif valable (certificat médical, attestation employeur).

Exemple : un candidat inscrit un mardi paie 160€, contre 180€ pour la même épreuve programmée un samedi dans le même centre.

> Comparez 2 ou 3 centres avant de vous inscrire : les tarifs et les délais d'inscription peuvent varier sensiblement d'une ville à l'autre.

## Comment LlamaKusi vous aide

LlamaKusi transforme cette préparation en méthode claire plutôt qu'en révisions dans le vide. Pendant que vous attendez votre session ou vos résultats, chaque minute compte pour progresser. Pas besoin d'attendre l'examen pour vous entraîner : le [Coach IA Oral](/tef-irn/oral) est inclus dans votre abonnement LlamaKusi. À l'approche de l'examen, un accompagnement ciblé fait souvent la différence — comparez les [offres Premium LlamaKusi](/tef-irn/pricing). Pour resituer ce point dans l'ensemble de votre dossier de naturalisation, consultez notre [guide complet Naturalisation & Démarches](https://llamakusi.com/tef-irn/guides/naturalisation-demarches-tef-irn-guide-complet).

## FAQ

**Le TEF IRN et le TCF IRN ont-ils les mêmes délais ?**
Les principes sont proches (convocation par email, validité 2 ans, délai de 20 jours entre deux tentatives), mais les délais exacts varient selon le centre et l'organisme (CCI Paris pour le TEF IRN, France Éducation International pour le TCF IRN).

**Puis-je repasser le TEF IRN si mon niveau n'est pas suffisant ?**
Oui, en respectant un délai minimum de 20 jours entre deux inscriptions au même test, et en payant à nouveau les frais d'inscription.

**Mon attestation TEF IRN papier est-elle acceptée si elle est expirée depuis quelques jours ?**
Non. L'attestation doit être en cours de validité au moment précis du dépôt de votre dossier, sans tolérance de quelques jours.

**Dois-je refaire tout le test si une seule épreuve est insuffisante ?**
Oui, les quatre épreuves doivent être repassées ensemble : il n'est pas possible de ne repasser qu'une seule compétence.
$CTA$ WHERE slug = 'inscription-tef-irn-delais';

UPDATE public.guides SET content = $CTA$# Fautes de Français Courantes : Les 10 Pièges à Éviter au TEF IRN

Vous répétez sans le savoir les mêmes fautes depuis des mois, malgré vos efforts. La bonne nouvelle : ce sont presque toujours les mêmes 10 réflexes, faciles à corriger une fois identifiés.

## Pourquoi confondre "tu" et "vous" nuit-il autant à l'oral ?

Utiliser "tu" dans un contexte formel donne immédiatement une impression de niveau débutant, même avec un vocabulaire riche.

Beaucoup d'apprenants ne perçoivent pas la nuance entre les deux pronoms dans leur langue maternelle et appliquent une seule forme partout. Face à un examinateur ou un interlocuteur inconnu ([l'expression orale du TEF IRN se déroule en entretien individuel face à face avec un examinateur](https://www.lefrancaisdesaffaires.fr/se-preparer-a-lepreuve-dexpression-orale-du-tef/)), le vouvoiement reste la norme par défaut. Ce réflexe se travaille consciemment jusqu'à devenir automatique.

Dire "tu peux m'aider ?" à un examinateur TEF IRN, au lieu de "pourriez-vous m'aider ?", marque immédiatement l'échange.

> Vouvoyez systématiquement tout inconnu à l'oral : c'est plus sûr que de deviner au cas par cas.

## L'oubli de l'élision fait-il vraiment mauvaise impression ?

Oui : dire "le avion" ou "la amie" au lieu de "l'avion" ou "l'amie" casse immédiatement la fluidité perçue par un interlocuteur natif.

Ce réflexe vient souvent d'une lecture mentale mot à mot, sans anticipation du mot suivant. Une fois automatisée à l'oral, l'élision rend la parole beaucoup plus naturelle, presque sans effort supplémentaire. C'est l'un des marqueurs de niveau les plus immédiats pour un auditeur francophone.

Un candidat qui dit "je vais à la école" au lieu de "je vais à l'école" attire l'attention sur ce détail plutôt que sur son message.

> Répétez à voix haute des groupes de mots fréquents avec élision (l'école, l'ami, l'an dernier) jusqu'à ce qu'ils sortent sans réfléchir.

## Pourquoi les accords du participe passé posent-ils autant de problèmes ?

Oublier d'accorder le participe passé avec l'auxiliaire "être" est l'une des erreurs les plus fréquentes, à l'écrit comme à l'oral.

Avec "être", le participe s'accorde toujours en genre et en nombre avec le sujet ; avec "avoir", il s'accorde uniquement si le complément d'objet direct est placé avant le verbe. Cette règle demande de la pratique répétée plutôt qu'une simple mémorisation théorique. Elle reste toutefois moins pénalisante à l'oral qu'à l'écrit, car l'accord ne s'entend pas toujours.

"Elle est allé au marché" au lieu de "elle est allée au marché" reste une erreur fréquente, même chez des candidats de niveau B1.

> Concentrez votre effort d'accord en priorité à l'écrit : c'est là que cette erreur se voit le plus clairement.

## Le genre des noms peut-il vraiment trahir un niveau débutant ?

Oui : se tromper de genre ("un table" au lieu de "une table") reste l'un des signaux les plus immédiats d'un niveau encore fragile.

Le genre grammatical français ne suit pas toujours de logique évidente pour un non-francophone, ce qui pousse à deviner plutôt qu'à mémoriser. Apprendre chaque nom directement avec son article ("la table", "le livre") évite de séparer artificiellement le mot de son genre. Cette habitude simple élimine progressivement l'hésitation au moment de parler.

Dire "mon voiture" au lieu de "ma voiture" reste audible immédiatement par un interlocuteur natif, même dans une phrase par ailleurs correcte.

> Notez chaque nouveau mot avec son article dès la première rencontre, jamais seul.

## Les prépositions après un verbe sont-elles si importantes ?

Oui : se tromper entre "penser à" et "penser de", ou "rêver de" et "rêver à", change parfois complètement le sens de la phrase.

Chaque verbe français impose sa propre préposition, sans logique transposable directement d'une autre langue. Apprendre le verbe et sa préposition comme un bloc unique, plutôt que séparément, évite cette confusion récurrente. Une vingtaine de verbes très courants suffisent à couvrir la majorité des situations du quotidien.

"Je pense de toi" au lieu de "je pense à toi" reste une confusion très fréquente chez les anglophones et hispanophones.

> Apprenez chaque verbe avec sa préposition dès le départ, sous forme de bloc ("penser à", "avoir besoin de").

## Pourquoi doubler la négation avec "pas" est-il incorrect ?

Utiliser "pas" en même temps qu'un autre mot négatif ("rien", "personne", "aucun") est une double négation incorrecte en français standard.

Contrairement à d'autres langues où renforcer la négation est naturel, le français exclut "pas" dès qu'un autre mot négatif est présent dans la phrase. "Je n'ai vu personne" est correct, alors que "je n'ai pas vu personne" ne l'est pas. Cette règle simple élimine une erreur qui revient très souvent à l'oral spontané.

Un candidat stressé qui dit "je n'ai pas rien compris" au lieu de "je n'ai rien compris" inverse involontairement le sens de sa phrase.

> Repérez les mots négatifs (rien, personne, aucun, jamais) : dès qu'un de ces mots apparaît, "pas" disparaît.

## Confondre passé composé et imparfait change-t-il vraiment le sens ?

Oui : le passé composé décrit une action ponctuelle et achevée, tandis que l'imparfait décrit un état ou une action en cours dans le passé.

Beaucoup d'apprenants choisissent l'un ou l'autre au hasard, faute de repère clair pour distinguer les deux usages. "Il est arrivé tard" (action ponctuelle) et "il était tard" (état) n'ont pas du tout le même sens, même si la traduction dans certaines langues semble identique. Une pratique régulière sur des récits courts aide à intérioriser cette distinction.

Raconter "hier, je mangeais un croissant" au lieu de "hier, j'ai mangé un croissant" change la nuance sans que le candidat s'en rende toujours compte.

> Avant de raconter un souvenir, demandez-vous si l'action est ponctuelle (passé composé) ou si elle décrit un état (imparfait).

## Traduire littéralement depuis sa langue maternelle pose-t-il problème ?

Oui : les traductions mot à mot ("réaliser" pour "s'apercevoir", venant de l'anglais "to realize") créent des phrases grammaticalement correctes mais peu naturelles.

Ce réflexe, appelé calque, reste invisible pour la personne qui parle mais très audible pour un interlocuteur natif. Apprendre des expressions idiomatiques complètes plutôt que des mots isolés réduit progressivement ce réflexe de traduction directe. Penser directement en français, même de façon simple, limite ce phénomène plus efficacement qu'une liste de vocabulaire isolé.

Dire "j'ai réalisé que j'étais en retard" dans un sens proche de l'anglais "to realize" sonne artificiel en français courant, où "je me suis rendu compte" est plus naturel.

> Apprenez des expressions entières plutôt que des mots isolés : cela réduit naturellement le réflexe de traduction littérale.

## Les liaisons interdites sont-elles vraiment un piège fréquent ?

Oui : faire une liaison là où elle est interdite trahit un niveau débutant aussi sûrement que l'oubli d'une liaison obligatoire.

La liaison après la conjonction "et" est un exemple classique : on ne lie jamais "et" au mot suivant, contrairement à d'autres liaisons fréquentes. Une liaison mal placée surprend l'oreille d'un locuteur natif, parfois davantage qu'une liaison manquante. Mémoriser les cas interdits les plus fréquents évite cette erreur ciblée.

Dire "un garçon-z-et une fille" au lieu de "un garçon et une fille" reste une liaison interdite très reconnaissable.

> Apprenez la liste des liaisons interdites les plus fréquentes : elles sont peu nombreuses et vite mémorisées.

## Trop hésiter avant de parler donne-t-il une mauvaise impression ?

Oui : une hésitation excessive avant chaque phrase donne une impression de niveau plus faible que la réalité, même avec une grammaire correcte.

Ce réflexe vient souvent de la peur de faire une erreur plutôt que d'un manque réel de vocabulaire ou de structure. S'entraîner à parler spontanément, y compris avec des erreurs, développe une fluidité que la révision silencieuse ne permet jamais d'atteindre. Les examinateurs valorisent généralement la fluidité et la clarté globale plus que la perfection grammaticale absolue, comme le détaille notre [guide sur l'Expression Orale Section A](https://llamakusi.com/tef-irn/guides/reussir-expression-orale-section-a).

Un candidat qui reformule mentalement chaque phrase avant de la dire perd un temps précieux à l'oral, en particulier lors d'un [échange chronométré](https://www.lefrancaisdesaffaires.fr/se-preparer-a-lepreuve-dexpression-orale-du-tef/) : les deux sections de l'épreuve d'expression orale du TEF durent respectivement 5 et 10 minutes.

> Entraînez-vous à parler sans vous arrêter, même en cas d'erreur : la fluidité se travaille séparément de la précision grammaticale.

## Comment LlamaKusi vous aide

La meilleure façon de progresser reste la pratique : essayez le [Coach IA Oral](/tef-irn/oral), qui repère vos erreurs récurrentes et vous corrige immédiatement. Pour éliminer ces réflexes avant votre passage à l'examen, les [offres Premium LlamaKusi](/tef-irn/pricing) proposent un suivi personnalisé de vos erreurs répétées. Si le stress de l'oral amplifie ces hésitations, une [méthode dédiée pour gagner en confiance](https://llamakusi.com/tef-irn/guides/gagner-confiance-en-francais) complète utilement cette liste. Retrouvez toutes nos ressources sur l'oral dans le [guide complet Expression Orale TEF IRN](https://llamakusi.com/tef-irn/guides/expression-orale-tef-irn-guide-complet).

## FAQ

**Ces erreurs pénalisent-elles vraiment la note au TEF IRN ?**
Certaines, comme le tutoiement inapproprié ou une double négation, sont plus visibles que d'autres à l'oral et peuvent affecter l'impression générale.

**Faut-il corriger les 10 erreurs en même temps ?**
Non, mieux vaut cibler 2 à 3 erreurs à la fois pour les corriger durablement avant de passer aux suivantes.

**Ces erreurs disparaissent-elles avec le niveau B2 ?**
Pas automatiquement : certaines, comme le genre des noms ou les prépositions, persistent parfois même à un niveau avancé sans entraînement ciblé.

**Comment savoir quelles erreurs je répète le plus ?**
Un retour immédiat sur vos productions orales, comme celui du Coach IA Oral, permet d'identifier rapidement vos erreurs récurrentes.......
