UPDATE public.guides SET content = $CTA$# Lecture Rapide TEF IRN : Techniques pour Réussir la Compréhension écrite

Un texte administratif inconnu et le chronomètre qui tourne suffisent à faire perdre ses moyens. Bonne nouvelle : l'épreuve s'adapte à votre niveau, et une méthode de lecture simple change tout.

## Pourquoi la compréhension écrite du TEF IRN fait-elle autant paniquer ?

La peur vient souvent d'un texte trop long ou trop technique découvert en pleine épreuve, sans possibilité de s'y préparer à l'avance.

Beaucoup de candidats se braquent devant un document administratif ou un article dense et perdent un temps précieux à vouloir tout comprendre mot à mot. Ce réflexe consomme l'attention nécessaire pour repérer les informations réellement utiles à la réponse. Il transforme une simple difficulté de vocabulaire en blocage sur toute la question.

Par exemple, un candidat qui bute sur le mot "préavis" dans un courrier de bailleur peut manquer la date de fin de contrat mentionnée juste après.

> Ne cherchez jamais à traduire chaque mot inconnu : concentrez-vous sur le sens global du passage.

## Comment se déroule l'épreuve de compréhension écrite du TEF IRN en 2026 ?

L'épreuve comporte **20 questions** réparties en deux parties de 10 questions, pour une durée totale de **30 minutes**.

La première partie propose 10 questions de difficulté variable, en 15 minutes, pour évaluer une première fois votre niveau. La seconde partie ajuste la difficulté des 10 questions suivantes à ce niveau estimé, toujours en 15 minutes ([source officielle CCI Paris Île-de-France](https://www.lefrancaisdesaffaires.fr/candidat/test-evaluation-francais/tef-irn/passation/)). Chaque question propose 4 réponses possibles, une seule étant correcte, et vous pouvez naviguer librement à l'intérieur de chaque partie.

Un candidat qui répond juste sur la première partie reçoit ensuite des documents légèrement plus complexes dans la seconde.

> Ne répondez jamais au hasard sur la première partie : elle détermine le niveau des questions qui suivent.

## Le format adaptatif change-t-il la façon de réviser ?

Oui : puisque la seconde partie s'ajuste à votre niveau réel, il devient inutile de réviser uniquement les textes les plus difficiles en espérant "forcer" un bon score.

Le format adaptatif limite le risque de tomber sur un document totalement hors de portée, mais il récompense surtout une préparation progressive sur plusieurs niveaux de difficulté plutôt qu'un pari sur un seul registre de texte. Un candidat qui ne s'entraîne que sur des textes B2 alors que son niveau réel est A2 risque de se déstabiliser inutilement sur la première partie. La régularité compte plus que l'intensité d'une seule révision.

Un candidat de niveau A2 qui s'entraîne aussi bien sur des annonces simples que sur des courriers plus formels aborde les deux parties avec plus de sérénité.

> Variez volontairement le niveau de difficulté de vos exercices, même quand un texte vous semble déjà acquis.

## Comment lire vite sans perdre les détails importants ?

La meilleure stratégie consiste à lire les questions et les propositions de réponse avant de lire le document en entier.

Cette lecture préalable oriente votre attention vers les informations réellement utiles : une date, un lieu, un montant, une condition. Elle évite de relire deux fois le même document faute d'avoir su, dès le départ, ce qu'il fallait y chercher. En anticipant, vous transformez une lecture passive en recherche active d'informations précises.

Par exemple, si la question porte sur "le délai à respecter", vous saurez dès le départ qu'il faut repérer cette information en priorité dans le texte.

> Repérez les mots-clés des questions avant de lire le document : ce sont vos repères pendant la lecture.

## TEF et TEF IRN : l'épreuve de compréhension écrite est-elle vraiment la même ?

Non, et cette confusion fait perdre du temps à de nombreux candidats qui révisent avec le mauvais format.

Le TEF "Tout Public" ou TEF Canada propose une épreuve de compréhension écrite de 40 questions en 60 minutes, sur des documents variés allant du texte lacunaire à la lecture rapide de graphiques. Le TEF IRN, réservé aux démarches d'intégration, de résidence et de naturalisation, ne reprend pas ce format : il se limite à 20 questions en 30 minutes, avec son mécanisme adaptatif propre. S'entraîner avec des exemples du TEF classique peut donc donner une fausse idée de la durée et du rythme réels de l'épreuve IRN.

Un candidat qui prépare sa naturalisation n'a donc pas besoin de s'entraîner sur les 40 questions d'un TEF généraliste, ce serait une perte de temps.

> Vérifiez systématiquement que vos exercices d'entraînement précisent bien "IRN" et non "Tout Public" ou "Canada".

## Quel entraînement progressif adopter avant l'examen ?

L'entraînement le plus efficace combine lecture régulière et diversité des types de documents.

Lire quotidiennement des courriers administratifs, des annonces ou de courts articles habitue l'œil à repérer vite l'information utile sans tout déchiffrer. Une [méthode de révision structurée sur plusieurs semaines](https://llamakusi.com/tef-irn/guides/comment-reviser-tef-irn-en-30-jours) permet de couvrir progressivement tous les types de documents rencontrés à l'épreuve. Mieux vaut 15 minutes ciblées chaque jour qu'une session longue et rare la veille de l'examen.

Un candidat qui s'entraîne sur des factures, des offres d'emploi et des messages courts couvre déjà une large partie des formats rencontrés à l'examen.

> Variez les types de documents : courrier, annonce, article, plutôt qu'un seul format toujours identique.

## Comment gérer le stress face à un texte inconnu le jour J ?

Le stress amplifie souvent la difficulté perçue d'un document, indépendamment de son niveau réel de complexité.

Savoir à l'avance que l'épreuve se déroule en deux parties chronométrées et connaître le déroulé exact du jour J réduit les mauvaises surprises qui déclenchent la panique. Un candidat qui sait déjà à quoi s'attendre concentre son énergie sur la lecture plutôt que sur l'inconnu du format. Travailler la confiance en amont fait souvent plus de différence que réviser du vocabulaire supplémentaire la veille.

Certains candidats se bloquent dès le premier document simplement parce qu'ils découvrent l'organisation de l'épreuve en même temps qu'elle commence.

> Si le trac vous paralyse habituellement, une [méthode dédiée pour gagner en confiance](https://llamakusi.com/tef-irn/guides/gagner-confiance-en-francais) peut compléter votre préparation à la lecture.

## Comment LlamaKusi vous aide

S'entraîner seul, sans retour sur ses erreurs, rend difficile de savoir où l'on progresse réellement sur la compréhension écrite — c'est exactement ce que corrige LlamaKusi. Des exercices de lecture calibrés sur votre niveau réel remplacent les révisions dans le vide. La [préparation Premium LlamaKusi](/tef-irn/pricing) couvre l'ensemble des quatre épreuves, et le [Coach IA Oral](/tef-irn/oral) reste disponible, avec votre abonnement, pour compléter votre entraînement au quotidien. Notre [guide complet Expression Écrite & Compréhension](https://llamakusi.com/tef-irn/guides/expression-ecrite-comprehension-tef-irn-guide-complet) couvre les 3 épreuves informatisées du TEF IRN.

## FAQ

**Combien de questions comporte l'épreuve de compréhension écrite du TEF IRN ?**
Elle comporte 20 questions réparties en deux parties de 10, pour une durée totale de 30 minutes.

**Une mauvaise réponse fait-elle perdre des points ?**
Non, aucun point n'est retiré en cas d'erreur ou d'absence de réponse. Répondez donc toujours, même en cas de doute.

**Le format adaptatif rend-il l'épreuve plus facile ?**
Il ne rend pas l'épreuve plus facile, mais il ajuste la difficulté des 10 dernières questions à votre niveau réel estimé sur les 10 premières.

**Le TEF Tout Public prépare-t-il vraiment à la compréhension écrite du TEF IRN ?**
Pas totalement : le format diffère nettement (40 questions en 60 minutes contre 20 questions en 30 minutes pour l'IRN), mieux vaut s'entraîner directement sur le format IRN.
$CTA$ WHERE slug = 'methodologie-comprehension-ecrite';

UPDATE public.guides SET content = $CTA$# Niveau B2 Naturalisation 2026 : Ce qui Change pour le TEF IRN

Vous pensiez votre niveau de français suffisant, et voilà que le seuil vient de changer sous vos pieds. Depuis le 1er janvier 2026, le niveau B2 remplace le B1 pour toute demande de naturalisation, mais un plan clair permet de rattraper cet écart.

## Pourquoi le niveau B2 est-il devenu obligatoire pour la naturalisation en 2026 ?

Depuis le **1er janvier 2026**, le décret n° 2025-648 du 15 juillet 2025 relève le niveau de français exigé du B1 au **B2** pour toute naturalisation par décret ou par mariage ([Légifrance](https://www.legifrance.gouv.fr/jorf/id/JORFTEXT000051900519)).

Ce texte modifie l'article 21-24 du Code civil et s'applique à l'oral comme à l'écrit, sans exception selon la voie d'accès à la nationalité. L'arrêté du 22 décembre 2025 précise la liste des tests et diplômes acceptés pour justifier ce niveau : TCF IRN, TEF IRN, DELF B2, DALF C1/C2, ou un diplôme français de niveau RNCP 3 ou plus. Ce relèvement s'inscrit dans un ensemble de réformes plus larges de la loi n° 2024-42 du 26 janvier 2024.

Un candidat visant la carte de résident reste soumis au niveau B1, seule la naturalisation impose désormais le B2.

> Vérifiez systématiquement la démarche visée avant de choisir votre niveau cible : B2 pour la naturalisation, B1 pour la carte de résident, A2 pour la carte de séjour pluriannuelle.

## Le niveau B1 obtenu avant 2026 est-il totalement perdu ?

Non, votre attestation B1 reste valable deux ans, mais elle ne suffit plus pour déposer une demande de naturalisation en 2026.

Ce qui compte légalement, c'est la date de dépôt du dossier complet, pas la date de passation du test. Un candidat ayant obtenu un B1 en décembre 2025 doit donc repasser un test attestant du niveau B2 avant de déposer son dossier, même si son attestation B1 est techniquement encore valide. Cette règle surprend de nombreux candidats qui pensaient leur niveau définitivement acquis.

Une attestation B1 passée fin 2025 reste utile pour une carte de résident, mais devient insuffisante pour une naturalisation déposée en 2026.

> Ne jetez pas votre ancienne attestation B1 : elle peut encore servir pour d'autres démarches que la naturalisation.

## Comment fonctionne le barème de points pour valider le niveau B2 ?

Pour le TCF IRN, il faut obtenir un score compris entre 500 et 599 points sur 699 pour valider le niveau B2 dans une épreuve donnée.

Chaque test (TCF ou TEF) attribue un score distinct à chacune des quatre compétences évaluées, sans moyenne globale entre elles. Un score B2 en compréhension écrite n'a donc aucun effet compensateur sur un score plus faible en expression orale. Cette logique de notation par compétence, indépendante d'une épreuve à l'autre, explique pourquoi une préparation équilibrée sur les quatre compétences est indispensable.

Un candidat obtenant 550 points en compréhension orale valide bien le B2 sur cette épreuve précise, indépendamment de son résultat aux trois autres.

> Demandez toujours le détail de votre score par épreuve, jamais uniquement une moyenne globale, pour savoir précisément où progresser.

## Pourquoi une seule épreuve trop faible peut-elle faire échouer tout le dossier ?

C'est le piège le plus mal anticipé : l'administration exige le niveau B2 dans les **quatre épreuves simultanément**, sans compensation possible.

Un candidat peut obtenir B2 en compréhension orale, compréhension écrite et expression écrite, mais rester bloqué en B1 en expression orale : son dossier est rejeté sur ce seul point, quels que soient ses excellents résultats ailleurs. Cette règle explique une part importante des [refus de naturalisation](https://llamakusi.com/tef-irn/guides/refus-dossier-prefecture-francais) liés au niveau de langue plutôt qu'à un dossier réellement incomplet. Identifier sa compétence la plus faible avant de se réinscrire évite de repasser le test sans avoir corrigé le bon point.

Un candidat très à l'aise à l'écrit mais peu entraîné à l'oral doit concentrer l'essentiel de sa préparation sur l'expression orale, pas répartir son temps également sur les quatre épreuves.

> Passez un test blanc complet avant de vous réinscrire, pour repérer précisément l'épreuve qui vous empêche encore d'atteindre le B2.

## Le niveau B2 remplace-t-il l'examen civique obligatoire ?

Non, ce sont deux exigences totalement distinctes et cumulatives depuis 2026 : le niveau B2 en français et la réussite de l'examen civique.

L'examen civique, prévu par l'arrêté du 10 octobre 2025, comporte 40 questions à choix multiples sur les valeurs, l'histoire et les institutions françaises, avec un seuil de réussite fixé à 32 sur 40 ([Légifrance](https://www.legifrance.gouv.fr/jorf/id/JORFTEXT000052381620)). Réussir le test de langue B2 ne dispense en rien de cette seconde obligation, et inversement. De nombreux candidats concentrent leur préparation sur un seul des deux volets en pensant qu'ils sont liés.

Un candidat titulaire d'un DELF B2 doit malgré tout présenter une attestation de réussite distincte à l'examen civique pour que son dossier soit complet.

> Préparez les deux exigences en parallèle plutôt que l'une après l'autre, pour ne pas retarder votre dépôt de dossier.

## Comment passer efficacement du niveau B1 au niveau B2 ?

La progression B1 vers B2 repose principalement sur la grammaire avancée, le vocabulaire abstrait et la nuance à l'oral, plus que sur des bases déjà acquises.

Le passage au B2 suppose de maîtriser des structures comme le subjonctif ou le conditionnel passé, souvent maîtrisées de façon incomplète au niveau B1. À l'oral, il s'agit surtout de développer la capacité à nuancer un avis, argumenter et défendre un point de vue plutôt que de simplement décrire une situation. Un [comparatif entre le TEF IRN et le TCF IRN](https://llamakusi.com/tef-irn/guides/tef-irn-vs-tcf-irn) permet de choisir le test le mieux adapté à votre progression avant de vous réinscrire.

Un candidat qui décrit correctement son quotidien au niveau B1 doit apprendre à défendre une opinion argumentée pour espérer valider le B2 à l'oral.

> Concentrez d'abord vos efforts sur la compétence la plus faible identifiée lors de votre test blanc, plutôt que de réviser uniformément les quatre épreuves.

## Combien de temps faut-il prévoir pour progresser de B1 à B2 ?

Comptez généralement entre 8 et 16 semaines de préparation ciblée pour combler l'écart entre B1 et B2, selon votre point de départ.

Ce délai varie fortement selon la compétence la plus faible à travailler : une lacune grammaticale se corrige souvent plus vite qu'une aisance orale insuffisante, qui demande une pratique régulière et prolongée. Mieux vaut prévoir une marge de sécurité avant votre échéance de dépôt plutôt que de vous réinscrire dans l'urgence avec un niveau encore fragile. Un délai minimum de 30 jours s'applique de toute façon entre deux tentatives en cas d'échec.

Un candidat visant un dépôt de dossier en fin d'année a intérêt à commencer sa préparation ciblée dès le début de l'été plutôt qu'à l'automne.

> Fixez-vous une date de test blanc à mi-parcours pour vérifier objectivement votre progression avant l'inscription définitive.

## Comment LlamaKusi vous aide

Si l'expression orale est votre point faible pour passer du B1 au B2, le [Coach IA Oral](/tef-irn/oral) vous permet de vous entraîner, avec votre abonnement, sur des mises en situation réelles. Vous progressez à votre rythme, avec un retour immédiat sur chaque échange. Pour une préparation structurée sur les quatre épreuves jusqu'au **niveau B2**, les [offres Premium LlamaKusi](/tef-irn/pricing) s'adaptent à votre point de départ et à votre échéance de dépôt. Retrouvez l'ensemble des informations clés sur l'examen dans notre [guide complet TEF IRN 2026](https://llamakusi.com/tef-irn/guides/tout-comprendre-tef-irn).

## FAQ

**Le niveau B2 s'applique-t-il aussi à la carte de résident ?**
Non, la carte de résident reste soumise au niveau B1, seule la naturalisation exige désormais le B2.

**Une attestation de comparabilité ENIC-NARIC est-elle encore acceptée ?**
Non, elle n'est plus acceptée comme justificatif de niveau depuis le 1er janvier 2026.

**Faut-il repasser les 4 épreuves si une seule est en dessous du B2 ?**
Oui, la plupart des tests imposent de repasser l'intégralité des épreuves, pas uniquement celle qui pose problème.

**Le niveau B2 est-il vérifié à la date du test ou à la date du dépôt du dossier ?**
C'est la date de dépôt du dossier complet qui compte, votre justificatif doit donc être valide et conforme à ce moment précis.
$CTA$ WHERE slug = 'niveaux-francais-naturalisation-2026';

UPDATE public.guides SET content = $CTA$# Échec TEF IRN : Délais, Plan de Révision et Solutions 2026

Vous venez de découvrir un score insuffisant et la panique monte ? Un échec au TEF IRN ne bloque pas votre dossier : voici le plan concret pour repartir dès maintenant.

## Combien de temps dois-je attendre avant de repasser le TEF IRN après un échec ?

Un **délai de carence de 20 jours** minimum est imposé entre deux passations du TEF IRN.

Ce délai est fixé par le [Français des affaires](https://www.lefrancaisdesaffaires.fr/candidat/conditions-dinscription-et-de-passation/) (CCI Paris Île-de-France), l'organisme certificateur, et s'applique à tous les candidats sans exception. Il existe aussi un délai pratique à prendre en compte : les places disponibles dans les centres agréés, qui peuvent allonger l'attente de plusieurs semaines selon la région et la période. Mieux vaut donc s'inscrire à la nouvelle session dès que le délai de 20 jours est écoulé, sans attendre le dernier moment.

**Exemple concret** : « J'ai reçu mon résultat le 5 du mois, je peux m'inscrire à une session à partir du 25. »

> Réservez votre nouvelle session dès que possible : les places partent vite dans les grands centres urbains.

## Dois-je repasser toutes les épreuves ou seulement celle où j'ai échoué ?

Il faut repasser l'intégralité des 4 épreuves, même si une seule était insuffisante.

Le TEF IRN ne permet aucun rattrapage partiel : compréhension orale, compréhension écrite, expression orale et expression écrite doivent toutes être repassées le même jour lors de la nouvelle session. Cela implique aussi de payer à nouveau l'intégralité des frais d'inscription, généralement entre **170 € et 250 €** selon le centre. C'est frustrant si une seule épreuve posait problème, mais cela signifie aussi que vous pouvez consolider vos points forts en même temps.

**Exemple concret** : Une candidate en échec uniquement à l'expression orale doit malgré tout repasser les 4 épreuves.

> Profitez de cette contrainte : révisez en priorité l'épreuve ratée, sans négliger totalement les 3 autres.

## Cet échec va-t-il bloquer mon dossier de préfecture ou de naturalisation ?

Non, un échec au TEF IRN n'est pas signalé à la préfecture et ne pénalise pas votre dossier en cours.

Seule l'attestation de résultats finale, valable **2 ans** ([service-public.fr](https://www.service-public.gouv.fr/particuliers/vosdroits/F11926)), compte pour votre démarche : la préfecture ne voit jamais vos tentatives précédentes. Le vrai risque n'est donc pas administratif mais lié au calendrier : si votre dossier a une échéance précise, chaque tentative ratée réduit la marge disponible pour obtenir une attestation valide à temps. Anticiper le nombre de sessions possibles avant votre échéance reste la meilleure protection.

**Exemple concret** : « Mon rendez-vous en préfecture est dans 3 mois, j'ai donc le temps de retenter une session avant. »

> Notez la date limite de votre démarche dès maintenant et comptez à rebours le nombre de sessions possibles.

## Quel plan concret mettre en place avant la prochaine session ?

Un plan efficace tient en 3 étapes : analyser l'échec, cibler la faiblesse, s'entraîner en conditions réelles.

Commencez par relire le détail de votre score par épreuve pour identifier précisément où les points ont manqué, plutôt que de tout réviser au hasard. Ensuite, concentrez l'essentiel du temps disponible sur cette compétence précise, en vous appuyant sur des exercices proches du format officiel. Notre [guide pour réviser le TEF IRN en 30 jours](https://llamakusi.com/tef-irn/guides/comment-reviser-tef-irn-en-30-jours) propose un planning complet adaptable à ce contexte de rattrapage.

**Exemple concret** : Un candidat faible en expression orale consacre 70 % de son temps de révision à des simulations orales chronométrées.

> Un plan court et ciblé sur 3 semaines est souvent plus efficace qu'une révision généraliste étalée sur 2 mois.

## Comment rester motivé après un échec au TEF IRN ?

Se concentrer sur les points gagnés plutôt que sur le score global aide à garder confiance pour la suite.

Un échec au TEF IRN touche énormément de candidats, y compris ceux qui maîtrisent bien le français à l'oral au quotidien : le format de l'examen se travaille spécifiquement, indépendamment du niveau de langue général. Revoir les épreuves où vous avez déjà de bons résultats permet de repartir avec une base solide plutôt qu'avec l'impression de tout recommencer. Notre [guide pour vaincre le trac à l'oral](https://llamakusi.com/tef-irn/guides/gagner-confiance-en-francais) détaille des méthodes concrètes pour aborder la nouvelle session plus sereinement.

**Exemple concret** : « J'avais 380 points en compréhension écrite, je garde cette méthode et je concentre mes efforts ailleurs. »

> Gardez une trace écrite de vos progrès entre les deux sessions : elle rassure plus qu'un simple ressenti.

## Comment LlamaKusi vous aide

LlamaKusi transforme cette préparation en méthode claire plutôt qu'en révisions dans le vide, surtout après un échec où le temps compte double. Un retour immédiat sur vos réponses permet de savoir exactement où concentrer vos efforts avant la prochaine session, plutôt que de réviser à l'aveugle. Pas besoin d'attendre l'examen pour vous entraîner : le [Coach IA Oral](/tef-irn/oral) est inclus dans votre abonnement LlamaKusi. À l'approche de la prochaine session, un accompagnement ciblé sur les 4 épreuves fait souvent la différence : comparez les [offres Premium LlamaKusi](/tef-irn/pricing). Pour une vue d'ensemble complète du TEF IRN (épreuves, niveaux, déroulement), consultez notre [guide complet 2026](https://llamakusi.com/tef-irn/guides/tout-comprendre-tef-irn).

## FAQ

**Combien de fois peut-on repasser le TEF IRN ?**
Il n'existe pas de limite officielle : vous pouvez repasser l'examen autant de fois que nécessaire, en respectant le délai de 20 jours entre deux sessions.

**Le score obtenu à un échec reste-t-il visible sur mon dossier ?**
Non, seule votre attestation finale valable 2 ans est transmise ; les tentatives précédentes ne sont pas communiquées à la préfecture.

**Puis-je contester mon résultat après un échec ?**
Un recours n'est possible qu'en cas de problème technique avéré lors de la passation, dans un délai maximum de 30 jours après l'édition de l'attestation.

**Faut-il changer de méthode de préparation après un échec ?**
Pas forcément : il s'agit surtout d'identifier l'épreuve la plus faible et d'y consacrer un entraînement ciblé plutôt que de tout reprendre à zéro.
$CTA$ WHERE slug = 'que-faire-si-je-rate-tef-irn';

UPDATE public.guides SET content = $CTA$# Refus Naturalisation 2026 : Les Erreurs à Éviter avec le TEF IRN

Vous redoutez la lettre de refus après des mois d'attente en préfecture. La plupart des rejets viennent d'erreurs évitables, pas d'un dossier réellement insuffisant.

## Pourquoi un dossier incomplet fait-il autant de refus de naturalisation ?

Un document manquant ou périmé suffit à bloquer l'instruction complète de votre demande.

L'administration vérifie chaque pièce d'état civil, de résidence et de ressources avant tout examen de fond. Une seule incohérence entre deux justificatifs peut être interprétée comme un manque de sérieux du dossier. Ce motif reste l'une des premières causes d'ajournement en **2026**, alors qu'il est le plus facile à éviter.

Un justificatif de domicile daté de plus de trois mois suffit parfois à faire classer un dossier comme incomplet.

> Faites relire votre dossier complet par une personne extérieure avant le dépôt, dates et pièces jointes comprises.

## Une traduction non assermentée peut-elle vraiment faire échouer une naturalisation ?

Oui : une traduction réalisée par un proche ou un traducteur non agréé n'a aucune valeur juridique pour la préfecture.

Les documents étrangers (actes de naissance, diplômes, jugements) doivent être traduits par un [traducteur assermenté inscrit auprès d'une cour d'appel française](https://www.service-public.gouv.fr/particuliers/vosdroits/F12956). Une traduction non conforme entraîne le rejet automatique de la pièce, parfois sans que le candidat en soit informé avant l'entretien. Ce point est particulièrement mal anticipé par les candidats venant de pays hors zone francophone.

Un acte de naissance traduit par un ami bilingue sera systématiquement écarté, même si la traduction est fidèle.

> Vérifiez que le traducteur figure bien sur la liste officielle d'une cour d'appel avant de payer la traduction.

## Le niveau B1 de français suffit-il encore pour la naturalisation en 2026 ?

Non : depuis le **[1er janvier 2026](https://www.legifrance.gouv.fr/jorf/id/JORFTEXT000051900519)**, le niveau **B2** à l'oral et à l'écrit est exigé pour la naturalisation par décret.

Un ancien diplôme de niveau B1, encore valable pour une carte de résident, ne suffit plus pour la nationalité française. Cette évolution surprend de nombreux candidats qui avaient préparé leur dossier avant la réforme. Le [niveau de français exigé pour la naturalisation](https://llamakusi.com/tef-irn/guides/niveaux-francais-naturalisation-2026) doit être vérifié précisément avant tout dépôt.

Un candidat titulaire d'un TCF de niveau B1 obtenu en 2024 doit repasser un test attestant du niveau B2.

> Vérifiez la date de validité et le niveau exact de votre attestation avant de déposer votre dossier.

## Les absences prolongées hors de France entraînent-elles un ajournement ?

Oui : tout séjour de plus de trois mois hors de France non justifié peut entraîner un ajournement du dossier.

L'administration exige une résidence stable et continue en France pendant toute la période de référence. Un voyage prolongé, un retour temporaire au pays ou une mission professionnelle longue doivent être documentés avec précision. L'absence de justificatif laisse penser à une rupture de résidence, même si la situation réelle du candidat est parfaitement régulière.

Un séjour de quatre mois à l'étranger pour raisons familiales, non justifié par des billets ou attestations, peut suffire à déclencher un ajournement.

> Conservez systématiquement les billets de transport et justificatifs de vos séjours à l'étranger, même courts.

## Un bilan OFII peut-il remplacer un diplôme de langue pour la naturalisation ?

Non, depuis **janvier 2026**, le bilan de compétences linguistiques OFII n'est plus accepté comme justificatif de niveau pour la naturalisation.

Seuls certains diplômes reconnus (TEF IRN, TCF IRN, DELF, DALF) ou un diplôme français de niveau suffisant sont désormais valables. Ce changement piège encore de nombreux candidats qui pensaient leur parcours d'intégration OFII suffisant. Vérifier la liste des justificatifs acceptés avant de préparer son dossier évite un refus tardif et coûteux en temps.

Un candidat présentant uniquement son bilan OFII de 2023 verra sa demande jugée irrecevable sur ce seul point.

> Ne vous fiez jamais à un justificatif ancien : vérifiez la liste actualisée des diplômes acceptés avant le dépôt.

## Pourquoi les incohérences entre les pièces du dossier posent-elles problème ?

Une différence de date, d'adresse ou d'emploi entre deux documents suffit à ralentir ou bloquer l'instruction.

L'administration croise systématiquement les informations entre l'état civil, les avis d'imposition, les contrats de travail et les justificatifs de domicile. Une incohérence, même mineure, peut être interprétée comme une tentative de dissimulation plutôt qu'une simple erreur de saisie. Une relecture croisée de l'ensemble des documents avant dépôt permet d'éviter ce piège fréquent.

Une adresse différente entre le bail et l'avis d'imposition de la même année déclenche souvent une demande de justification supplémentaire.

> Listez chaque information clé (dates, adresses, emplois) et vérifiez qu'elle est identique sur tous les documents.

## L'absence de preuves d'intégration suffit-elle à expliquer un refus ?

Se limiter aux justificatifs strictement obligatoires affaiblit un dossier par ailleurs conforme.

L'administration apprécie l'intégration dans son ensemble : vie associative, engagement local, scolarité des enfants, stabilité professionnelle. Un dossier qui ne présente que le minimum légal donne une image incomplète du parcours réel du candidat. Ajouter des preuves complémentaires renforce la crédibilité de la demande sans complexifier la procédure. D'ailleurs, [le TEF IRN ne suffit pas à lui seul](https://llamakusi.com/tef-irn/guides/tef-irn-ne-suffit-pas) pour garantir un dossier solide : le niveau de langue n'est qu'une pièce parmi d'autres.

Une attestation de bénévolat ou un certificat de scolarité des enfants peut faire la différence lors de l'entretien préfectoral.

> Joignez toute preuve concrète de votre vie en France, même si elle n'est pas exigée dans la liste officielle.

## L'échec à l'examen civique peut-il faire échouer toute la demande ?

Oui : depuis le **1er janvier 2026**, la réussite de l'examen civique est une condition obligatoire pour la naturalisation.

Ce test évalue la connaissance des valeurs républicaines, des institutions et du fonctionnement de la société française. De nombreux candidats concentrent leur préparation sur le niveau de français et négligent cette épreuve, pourtant tout aussi éliminatoire. Une préparation ciblée sur les thèmes officiels réduit considérablement ce risque.

Un candidat maîtrisant parfaitement le français peut voir son dossier ajourné faute d'avoir révisé les questions civiques.

> Ne traitez jamais l'examen civique comme une formalité : il conditionne votre dossier au même titre que le niveau de français.

## Comment LlamaKusi vous aide

Si le niveau de français vous inquiète pour votre dossier de naturalisation, le [Coach IA Oral](/tef-irn/oral) permet de s'entraîner en conditions réelles, avec votre abonnement. Vous progressez à votre rythme vers le **niveau B2** exigé depuis 2026, avec un retour immédiat sur chaque passage. Pour un accompagnement complet vers votre échéance de dépôt, les [offres Premium LlamaKusi](/tef-irn/pricing) s'adaptent à votre niveau et à votre calendrier. Notre [guide complet sur la naturalisation et les démarches](https://llamakusi.com/tef-irn/guides/naturalisation-demarches-tef-irn-guide-complet) couvre l'ensemble du dossier, au-delà du seul niveau de français.

## FAQ

**Combien de temps ai-je pour contester un refus de naturalisation ?**
Vous disposez généralement de deux mois pour former un recours gracieux ou hiérarchique après notification du refus.

**Quelle est la différence entre un ajournement et un refus ?**
L'ajournement signifie que le dossier n'est pas encore assez solide, avec possibilité de redéposer après un délai. Le refus est une décision plus définitive, contestable uniquement par recours.

**Puis-je connaître les motifs exacts d'un refus ?**
Oui, vous pouvez demander votre dossier complet via la CADA si les motifs communiqués restent trop vagues.

**Faut-il un avocat pour contester un refus de naturalisation ?**
Ce n'est pas obligatoire, mais fortement recommandé pour un recours contentieux devant le tribunal administratif.
$CTA$ WHERE slug = 'refus-dossier-prefecture-francais';

UPDATE public.guides SET content = $CTA$# Essai Argumentatif TEF IRN : Structure pour la Section B

Vous bloquez devant la page blanche de l'essai argumentatif ? Voici la structure en trois temps pour transformer cette angoisse en méthode claire et viser le **niveau B2**.

## Qu'est-ce que la Section B de l'Expression Écrite du TEF IRN ?

La Section B vous demande de défendre une **opinion argumentée** sur un sujet de société, en 200 mots minimum.

Contrairement à la Section A, qui prolonge un fait divers avec un ton neutre, la Section B est souvent surnommée à tort « l'épreuve de la lettre ». Aucun format épistolaire n'est en réalité obligatoire : l'objectif est d'exposer un point de vue personnel, clairement structuré, en s'appuyant sur des arguments et des exemples concrets tirés de la vie courante.

Exemple concret : face à l'énoncé « Le télétravail favorise-t-il vraiment l'équilibre de vie ? », vous choisissez une position (favorable ou non) et vous la défendez du début à la fin sans vous contredire.

> Fixez votre position dès la première ligne : un avis qui varie en cours de texte pénalise la cohérence globale.

## Quelle structure adopter pour réussir l'essai argumentatif ?

La structure gagnante tient en trois blocs : une introduction courte qui annonce la position, un développement de 2 à 3 arguments illustrés, puis une conclusion qui résume sans ajouter d'idée neuve.

Cette architecture simple rassure le correcteur autant qu'elle vous rassure vous-même le jour de l'examen. Elle évite le principal piège de cette épreuve : le texte qui part dans plusieurs directions faute de plan préalable. Consacrer 3 à 4 minutes à noter votre position et vos arguments avant d'écrire change radicalement la qualité du résultat final.

Exemple concret : « Je pense que le télétravail améliore l'équilibre de vie. Premièrement... Deuxièmement... En conclusion, je reste convaincu que ce mode d'organisation profite à la majorité des salariés. »

> Notez votre plan en 5 mots-clés sur un brouillon avant de rédiger : cela évite les hors-sujets qui coûtent le plus de points.

## Combien d'arguments faut-il développer pour viser le niveau B2 ?

Deux à trois arguments solides et bien illustrés valent largement mieux que cinq arguments effleurés en surface.

Le niveau **B2** suppose de développer une idée avec nuance plutôt que d'empiler des affirmations. Chaque argument mérite une phrase d'explication et un exemple concret qui l'ancre dans une situation réelle. Un candidat qui maîtrise deux arguments approfondis, avec une concession bien amenée, obtient un texte plus convaincant qu'une liste de points non développés.

Exemple concret : « Certes, le télétravail peut isoler certains salariés. Cependant, il libère un temps de trajet réinvesti dans la vie personnelle. »

> Une concession suivie d'un « cependant » montre une vraie maturité argumentative, particulièrement valorisée au niveau B2.

## Quels connecteurs logiques utiliser pour gagner en cohérence ?

Varier les connecteurs logiques (d'abord, de plus, cependant, par conséquent, en revanche) montre au correcteur une maîtrise linguistique proche du **niveau B2**.

Une vingtaine de connecteurs bien choisis suffit à élever nettement le niveau perçu de votre copie, à condition qu'ils relient des idées réellement liées entre elles et non qu'ils soient juxtaposés artificiellement. Éviter de répéter le même connecteur d'un paragraphe à l'autre est un signal simple mais efficace pour le correcteur.

Exemple concret : « Par conséquent, une politique claire de télétravail réduit les tensions internes liées aux trajets domicile-travail. »

> Réservez « en revanche » et « cependant » pour introduire une vraie nuance, jamais pour remplir l'espace artificiellement.

## Comment est corrigée la Section B par les évaluateurs du TEF IRN ?

L'épreuve d'Expression Écrite est évaluée par deux correcteurs indépendants, sur une copie rendue anonyme, selon des critères alignés sur le **CECRL**.

Ces critères couvrent généralement la pertinence du contenu par rapport au sujet, la cohérence de l'organisation des idées, la correction grammaticale et la richesse du vocabulaire employé. Depuis le [1er janvier 2026](https://www.service-public.gouv.fr/particuliers/vosdroits/F11926), le niveau **B2** est exigé à l'écrit comme à l'oral pour une demande de naturalisation, ce qui suppose un score global élevé sur l'ensemble des épreuves du TEF IRN, [conformément aux exigences détaillées pour la naturalisation](https://llamakusi.com/tef-irn/guides/niveaux-francais-naturalisation-2026).

Exemple concret : deux copies identiques en contenu mais avec des niveaux de langue différents peuvent recevoir des notes très différentes de la part des deux correcteurs.

> Un texte hors-sujet, même bien écrit, reçoit une pénalité sévère : relisez la consigne deux fois avant de commencer.

## Quelles erreurs évitent les candidats qui réussissent cette épreuve ?

Les candidats qui réussissent évitent trois pièges : le hors-sujet, la répétition de mots simples comme « il y a » ou « faire », et l'absence totale de plan.

Le hors-sujet reste la faute la plus fréquente et la plus coûteuse, souvent causée par une lecture trop rapide de la consigne. La répétition de verbes passe-partout donne une impression de vocabulaire pauvre, alors que des synonymes simples suffisent à corriger ce point. Enfin, un texte rédigé sans brouillon dérive fréquemment vers la fin, ce qui nuit à la cohérence globale évaluée par le correcteur.

Exemple concret : remplacer « il y a beaucoup d'avantages » par « cette mesure présente plusieurs avantages » change immédiatement la perception du niveau de langue.

> Relisez votre texte une dernière fois en traquant uniquement les répétitions de mots simples : ce réflexe de 2 minutes améliore nettement la note finale.

## Comment LlamaKusi vous aide

Chez LlamaKusi, l'objectif est simple : vous faire progresser plus vite grâce à un retour immédiat sur vos essais argumentatifs. Plutôt que de rédiger dans le vide, vous obtenez une correction détaillée de votre structure, de vos connecteurs et de votre niveau de langue réel. Cette méthode complète utilement votre entraînement à la [Section A de l'Expression Écrite](https://llamakusi.com/tef-irn/guides/reussir-expression-ecrite-section-a), pour couvrir l'ensemble de l'épreuve.

Envie de savoir où vous en êtes vraiment ? Testez le [Coach IA Oral](/tef-irn/oral) dans le cadre de votre abonnement LlamaKusi, pour compléter votre préparation à l'écrit comme à l'oral. Chaque profil est différent : les [formules Premium LlamaKusi](/tef-irn/pricing) s'adaptent à votre niveau et à votre échéance. Retrouvez toutes nos méthodes pour l'écrit et la compréhension dans le [guide complet dédié](https://llamakusi.com/tef-irn/guides/expression-ecrite-comprehension-tef-irn-guide-complet).

## FAQ

**Combien de temps ai-je pour rédiger la Section B ?**
L'[Expression Écrite dure 30 minutes au total](https://www.lefrancaisdesaffaires.fr/candidat/test-evaluation-francais/tef-irn/presentation/) pour les deux sections, à répartir vous-même entre la Section A et la Section B.

**Dois-je absolument écrire une lettre pour la Section B ?**
Non, ce n'est pas obligatoire. L'objectif est d'exposer un point de vue argumenté, sous n'importe quelle forme cohérente.

**Combien de mots minimum sont attendus ?**
200 mots minimum sont généralement demandés pour cette section, sans pénalité automatique au-delà de ce seuil.

**Quel niveau dois-je atteindre pour la naturalisation ?**
Le niveau **B2** est exigé à l'écrit et à l'oral depuis janvier 2026 pour une demande de naturalisation française.

**Puis-je changer d'avis en cours de rédaction ?**
Mieux vaut l'éviter : un avis qui varie en cours de texte nuit à la cohérence, un critère directement évalué par les correcteurs.
$CTA$ WHERE slug = 'reussir-expression-ecrite-section-b';

UPDATE public.guides SET content = $CTA$# Résultats TEF IRN : Comprendre les Scores et Seuils par Niveau

Vous venez de passer le TEF IRN ou vous vous préparez, et une question revient sans cesse : votre score sera-t-il **dans la moyenne** ? La bonne nouvelle : ce qui compte vraiment n'est pas une moyenne nationale, mais votre position par rapport aux seuils officiels.

## Existe-t-il un score moyen officiel publié par la CCI Paris IDF ?

Non, aucun score moyen national du TEF IRN n'est publié officiellement par la CCI Paris Île-de-France.

L'organisme communique le barème par épreuve (de **0 à 499 points**) et les seuils de niveaux, mais ne diffuse pas de statistique de moyenne générale des candidats. Cette absence de donnée publique explique pourquoi tant de candidats cherchent une réponse sans jamais la trouver clairement.

Par exemple, un candidat qui tape "score moyen TEF IRN" tombe systématiquement sur des explications du barème, jamais sur un vrai chiffre de moyenne.

> Plutôt que de chercher une moyenne qui n'existe pas, comparez votre score aux **seuils officiels** : c'est la seule référence fiable et vérifiable.

## Comment savoir si mon score est bon par rapport aux autres candidats ?

Un score est "bon" quand il dépasse le seuil du niveau CECRL visé par votre démarche, pas une moyenne théorique.

Le [barème officiel](https://www.francecompetences.fr/recherche/rs/6775/) fonctionne par tranches : **200 à 299 points** pour le niveau A2, **300 à 399** pour le niveau B1, **400 à 499** pour le niveau B2. Depuis le 1er janvier 2026, la carte de séjour pluriannuelle demande le niveau A2, la carte de résident le niveau B1, et la naturalisation le niveau B2. Se comparer aux autres candidats a donc peu de sens : ce qui compte, c'est votre score par rapport au seuil de **votre** démarche.

Exemple concret : un candidat visant la naturalisation avec 385 points en expression orale n'est pas "dans la moyenne", il est simplement encore en dessous du seuil B2 fixé à 400.

> Notez toujours votre objectif précis (A2, B1 ou B2) avant de juger un score : "bon" ou "moyen" ne veut rien dire sans cette référence.

## Quelle règle permet d'être "un peu moins bon" sur une épreuve sans perdre son niveau ?

Le TEF IRN autorise une épreuve légèrement en dessous du seuil, à condition que les trois autres l'atteignent.

Concrètement, pour [valider le niveau B2](https://www.lefrancaisdesaffaires.fr/candidat/test-evaluation-francais/tef-irn/resultats/), il faut au moins **400 points** dans 3 épreuves sur 4, et au moins **367 points** dans la quatrième. La même logique s'applique au niveau B1 (300/267) et au niveau A2 (200/167). Cette marge existe précisément parce que peu de candidats obtiennent un score parfaitement homogène sur les quatre épreuves.

Un candidat avec 420, 410 et 405 points en compréhension écrite, orale et expression écrite, mais 375 en expression orale, valide quand même le niveau B2 grâce à cette règle.

> Vérifiez toujours votre épreuve la plus faible en premier : c'est souvent elle qui détermine votre niveau final, pas votre meilleure note.

## Quelle épreuve fait le plus souvent baisser le résultat global des candidats ?

L'expression orale reste, selon les retours de terrain des centres de préparation, l'épreuve la plus redoutée et la plus souvent en dessous des autres scores.

Contrairement aux épreuves de compréhension, notées en QCM automatisé, l'expression orale est évaluée en face-à-face par un examinateur sur des critères précis : aisance, lexique, grammaire, organisation du discours. Le stress de l'oral en temps réel joue un rôle que les révisions seules ne suffisent pas toujours à compenser.

Un candidat parfaitement à l'aise à l'écrit peut ainsi perdre plusieurs dizaines de points à l'oral simplement par manque d'entraînement en conditions réelles.

> Concentrez une part importante de votre préparation sur l'oral, même si vous vous sentez plus fort à l'écrit : c'est souvent là que se joue le niveau final.

## Comment connaître rapidement mon propre positionnement avant de passer l'examen ?

La seule façon fiable de savoir où vous en êtes est de vous entraîner en conditions proches de l'examen, avec un retour immédiat sur votre performance.

Un score simulé sur une épreuve blanche donne une estimation bien plus utile qu'une moyenne théorique introuvable. Cela permet d'identifier concrètement l'épreuve qui vous ferait perdre des points le jour J, et de corriger le tir avant qu'il ne soit trop tard.

Un candidat qui teste sa compréhension orale une semaine avant l'examen découvre parfois un écart de 50 points avec ce qu'il pensait maîtriser.

> Testez-vous régulièrement plutôt qu'une seule fois : votre positionnement évolue à chaque semaine d'entraînement.

## Comment LlamaKusi vous aide

Envie de savoir où vous en êtes vraiment ? Testez le [Coach IA Oral](/tef-irn/oral) dans le cadre de votre abonnement LlamaKusi. Il vous donne un retour immédiat sur votre expression orale, l'épreuve qui fait le plus souvent basculer un score en dessous du seuil visé. Vous pouvez aussi consulter notre guide sur le [taux de réussite au TEF IRN par niveau](https://llamakusi.com/tef-irn/guides/taux-de-reussite-tef-irn) pour compléter votre positionnement. Pour un suivi complet et une correction détaillée de chaque passage, découvrez les [offres Premium LlamaKusi](/tef-irn/pricing). Si vous démarrez tout juste votre préparation, notre [guide complet sur le TEF IRN](https://llamakusi.com/tef-irn/guides/tout-comprendre-tef-irn) reprend l'essentiel : épreuves, niveaux et déroulement du jour J.

## FAQ

**Le TEF IRN publie-t-il un classement des candidats ?**
Non, il n'existe aucun classement public ni comparaison directe entre candidats. Seul votre score individuel compte pour votre démarche.

**Un score de 350 points est-il un bon score ?**
Cela dépend de votre objectif : 350 points valide le niveau B1, suffisant pour une carte de résident, mais pas pour la naturalisation qui exige B2.

**Puis-je repasser uniquement l'épreuve où j'ai le score le plus bas ?**
Non, le TEF IRN s'inscrit sous forme d'un bloc de quatre épreuves insécables. En cas d'échec, vous devez tout repasser après un délai de 30 jours.

**Existe-t-il des statistiques par centre d'examen ?**
Certains centres publient occasionnellement leurs propres taux de réussite par session, mais ces données restent locales et ne reflètent pas une moyenne nationale.

**Comment savoir précisément quel score viser pour ma démarche ?**
Consultez le [guide sur les niveaux exigés pour la naturalisation](https://llamakusi.com/tef-irn/guides/niveaux-francais-naturalisation-2026) pour connaître le seuil exact selon votre situation en 2026.
$CTA$ WHERE slug = 'score-moyen-tef-irn';

UPDATE public.guides SET content = $CTA$# Français du Quotidien : 10 Phrases pour la Vie en France (A1-A2)

Vous redoutez le moment où il faudra parler français à la boulangerie ou chez le médecin ? Voici les **phrases essentielles pour le français quotidien**, utilisables dès le niveau A1.

## Quelles phrases dire pour acheter du pain à la boulangerie ?

Trois phrases suffisent pour acheter du pain sans stress : saluer, nommer ce que vous voulez, remercier.

En France, le rituel social compte souvent plus que la grammaire parfaite. Un "bonjour" en entrant et un "merci, au revoir" en sortant sont attendus dans presque tous les commerces, même pour un achat de trente secondes. Le vocabulaire de base reste très stable d'une boulangerie à l'autre : type de pain, quantité, mode de paiement.

**Exemple concret** : « Bonjour, une baguette tradition, s'il vous plaît. » — « Ce sera tout ? » — « Oui, merci, au revoir. »

> Dire "bonjour" en entrant et "merci, au revoir" en sortant compte presque plus que la phrase elle-même en France.

## Comment expliquer un problème de santé chez le médecin ou en pharmacie ?

Une phrase simple sur le symptôme, suivie de sa durée, suffit pour se faire comprendre.

Le pharmacien peut souvent conseiller directement sans rendez-vous ([ameli.fr](https://www.ameli.fr/assure/sante/medicaments/missions-pharmacien)), tandis que le médecin généraliste est nécessaire pour une ordonnance ou un arrêt de travail. Les formules "j'ai mal à...", "je voudrais un rendez-vous" et "avez-vous quelque chose contre..." couvrent la grande majorité des situations de **français quotidien pour immigrés** en matière de santé. Préciser depuis combien de temps dure le symptôme aide beaucoup l'interlocuteur.

**Exemple concret** : « Bonjour, j'ai mal à la gorge depuis trois jours. Avez-vous quelque chose contre ça ? »

> Montrer la zone douloureuse du doigt aide toujours si le mot exact vous manque.

## Quelles phrases utiliser dans les transports en commun ?

"Bonjour" + destination + "s'il vous plaît" suffisent pour un ticket ou un renseignement.

Dans le bus, le métro ou le train, les agents et les autres voyageurs répondent presque toujours de bonne grâce à une question simple et polie. La phrase la plus utile reste celle qui permet de vérifier un itinéraire avant de monter, pour éviter de se tromper de direction. Ne pas comprendre une réponse n'est jamais un problème si vous savez demander une répétition.

**Exemple concret** : « Excusez-moi, ce bus va bien à la gare ? »

> Gardez toujours en tête une phrase de secours : "Pouvez-vous répéter, s'il vous plaît ?" — personne ne s'en formalise.

## Comment se présenter et remplir un dossier à la mairie ou en préfecture ?

Présenter son nom et l'objet précis de sa visite en une seule phrase claire facilite l'accueil.

Depuis le **1er janvier 2026** ([service-public.gouv.fr](https://www.service-public.gouv.fr/particuliers/vosdroits/F34501)), de nouvelles exigences linguistiques s'appliquent pour les demandes de carte de séjour pluriannuelle, de carte de résident et de naturalisation, avec un **niveau A2** désormais requis pour la carte de séjour pluriannuelle. Savoir formuler l'objet de sa démarche ("renouvellement", "première demande", "changement d'adresse") en une phrase évite les allers-retours au guichet. Si vous visez précisément cette démarche, notre [guide complet sur le TEF IRN niveau A2 pour la carte de séjour](https://llamakusi.com/tef-irn/guides/tef-irn-carte-sejour-A2) détaille toutes les étapes.

**Exemple concret** : « Bonjour, je viens pour le renouvellement de ma carte de séjour. J'ai rendez-vous à 10 heures. »

> À l'approche d'un rendez-vous en préfecture, un accompagnement ciblé fait souvent la différence — comparez les [offres Premium LlamaKusi](/tef-irn/pricing) pour vous préparer sereinement.

## Que dire en cas d'urgence ou pour demander de l'aide dans la rue ?

Un mot-clé du problème, dit clairement, suffit pour être compris rapidement en urgence.

Face à une pharmacie fermée, un objet perdu ou un besoin d'orientation, la priorité est la clarté, pas la perfection grammaticale. Les formules "j'ai besoin d'un médecin", "où est la pharmacie la plus proche" et "pouvez-vous m'aider" fonctionnent dans presque toutes les situations imprévues. Une fois ces phrases de base maîtrisées, il devient utile de corriger les tournures les plus fréquentes en français grâce à notre [guide sur les erreurs de français courantes](https://llamakusi.com/tef-irn/guides/les-10-erreurs-de-francais).

**Exemple concret** : « Excusez-moi, pouvez-vous m'aider ? Je cherche la pharmacie la plus proche. »

> En urgence, un mot juste et un geste clair valent mieux qu'une phrase parfaite mais hésitante.

## Comment LlamaKusi vous aide

Chez LlamaKusi, l'objectif est simple : vous faire progresser plus vite grâce à un retour immédiat sur vos phrases du quotidien. Ces expressions sont un excellent point de départ, mais l'épreuve orale du TEF IRN demande aussi de savoir les adapter face à un examinateur, sans les réciter par cœur. Envie de savoir où vous en êtes vraiment ? Testez le [Coach IA Oral](/tef-irn/oral) dans le cadre de votre abonnement LlamaKusi, pour vous entraîner sur des mises en situation réalistes. Pour une vue d'ensemble de l'épreuve orale (sections A et B, notation, gestion du trac), consultez notre [guide complet Expression Orale](https://llamakusi.com/tef-irn/guides/expression-orale-tef-irn-guide-complet).

## FAQ

**Quel niveau CECRL faut-il pour ces phrases de survie ?**
Le niveau **A1** suffit pour la plupart de ces situations ; quelques formules relèvent du niveau A2, notamment pour les démarches administratives.

**Combien de temps pour mémoriser ces phrases ?**
Quelques jours de répétition quotidienne à voix haute suffisent généralement pour les retrouver naturellement au bon moment.

**Ces phrases suffisent-elles pour réussir le TEF IRN ?**
Elles couvrent bien la vie courante, mais l'examen évalue aussi votre capacité à réagir à l'imprévu, d'où l'intérêt de s'entraîner davantage à l'oral.

**Que faire si je ne comprends pas la réponse de mon interlocuteur ?**
Utilisez simplement "Pouvez-vous répéter, s'il vous plaît ?" ou "Plus lentement, s'il vous plaît" : ces phrases sont toujours bien accueillies.
$CTA$ WHERE slug = 'survivre-en-francais-quotidien';

UPDATE public.guides SET content = $CTA$# Taux de Réussite TEF IRN 2026 : Statistiques par Niveau (A2, B1, B2)

Vous doutez de vos chances au TEF IRN ? Les chiffres disponibles rassurent : la majorité des candidats préparés réussissent, même si l'écart se creuse selon le niveau visé.

## Existe-t-il un taux de réussite officiel au TEF IRN en 2026 ?

Non, la **CCI Paris Île-de-France** ne publie pas de taux de réussite national agrégé pour le TEF IRN. Les seules données publiques viennent de centres d'examen ou de formation individuels, qui communiquent leurs propres résultats. Ces chiffres ne représentent donc pas une moyenne nationale fiable, mais ils donnent une tendance utile. Par exemple, l'organisme ALIP a annoncé un **taux de réussite global de 78,5%** sur l'année 2024-2025, pour 1 090 candidats ayant passé l'examen IRN. C'est un ordre de grandeur réaliste pour un candidat correctement préparé, pas une garantie individuelle.

> Méfiez-vous des chiffres marketing du type "97% de réussite" affichés sans méthode ni période précisée : sans contexte, ils ne veulent rien dire.

## Le taux de réussite varie-t-il selon le niveau visé (A2, B1, B2) ?

Oui, très nettement. Plus le niveau exigé est élevé, plus le taux de réussite par épreuve baisse. Des données de sessions passées montrent des taux de réussite en **compréhension écrite et orale au-dessus de 90%** pour un niveau A2, contre des taux nettement plus bas pour un niveau **B1**. La marge entre A2 et B1 est la plus significative, ce qui reflète le saut de complexité entre les deux niveaux. Depuis **janvier 2026**, le niveau A2 suffit pour la [carte de séjour pluriannuelle, le B1 pour la carte de résident](https://www.service-public.gouv.fr/particuliers/vosdroits/F34501), et le **B2** est désormais exigé pour la naturalisation.

Exemple concret : un candidat visant le niveau A2 pour sa carte de séjour a statistiquement bien plus de marge qu'un candidat visant le B2 pour sa naturalisation, où chaque épreuve doit être maîtrisée sans faiblesse majeure.

> Si vous visez la naturalisation, ne vous entraînez jamais uniquement sur le niveau A2 : le saut d'exigence vers le B2 est trop important pour l'improviser.

## Quelle épreuve fait le plus souvent échouer les candidats ?

L'**Expression Écrite** est, de loin, l'épreuve la plus discriminante à mesure que le niveau exigé augmente. Sur des sessions passées, le taux de réussite à l'Expression Écrite pour un niveau B1 est tombé autour de **51 à 58%**, quand la Compréhension Orale ou Écrite dépassait les 75-80% sur le même niveau. L'Expression Orale, à l'inverse, affiche généralement des taux de réussite très élevés, souvent supérieurs à 90%, y compris aux niveaux élevés. Cet écart s'explique par la difficulté à structurer un texte argumentatif clair en temps limité, une compétence qui demande un entraînement spécifique.

Exemple : un candidat à l'aise à l'oral mais peu habitué à rédiger un texte structuré en 20 minutes se fait souvent piéger par l'Expression Écrite, alors qu'il maîtrise le reste.

> Ne négligez jamais l'Expression Écrite dans votre préparation : c'est statistiquement l'épreuve la plus risquée, quel que soit votre niveau oral.

## Le durcissement des niveaux exigés depuis janvier 2026 a-t-il un impact sur ces chiffres ?

Probablement, même si aucune donnée agrégée récente ne le confirme encore précisément. Depuis le [1er janvier 2026, les niveaux requis ont été relevés](https://www.legifrance.gouv.fr/jorf/id/JORFTEXT000051900519) pour toutes les démarches : A2 pour la carte de séjour, B1 pour la carte de résident, B2 pour la naturalisation. Un niveau plus haut exigé mécaniquement pour la même démarche tend à faire baisser le taux de réussite brut, puisque l'épreuve est objectivement plus difficile à réussir. La naturalisation, en particulier, demande désormais une maîtrise B2 à l'écrit et à l'oral, un niveau nettement plus exigeant que le B1 auparavant requis.

> Si votre dossier est en cours depuis avant 2026, vérifiez bien le niveau qui s'applique réellement à votre situation auprès de la préfecture.

## Comment interpréter ces chiffres pour évaluer ses propres chances ?

Le taux de réussite global ne dit rien sur votre cas personnel : il reflète une moyenne, pas votre niveau de préparation. Un candidat qui s'entraîne avec des exercices proches du format réel de l'examen a statistiquement de meilleures chances qu'un candidat qui révise sans méthode. Les données disponibles montrent surtout que l'échec est concentré sur des points précis (Expression Écrite, niveaux élevés), pas de façon uniforme sur toutes les épreuves.

Exemple : deux candidats visant le B1 peuvent avoir des chances très différentes selon qu'ils ont ou non travaillé spécifiquement l'Expression Écrite en amont.

> Concentrez votre préparation sur vos points faibles réels plutôt que de réviser uniformément toutes les épreuves.

## Comment LlamaKusi vous aide

Comment s'entraîner efficacement sans y passer des heures chaque jour ? En identifiant précisément vos points faibles réels, notamment sur les épreuves les plus discriminantes comme l'Expression Écrite. Testez le [Coach IA Oral](/tef-irn/oral) avec votre abonnement, pour évaluer votre niveau réel à l'oral. Pour une préparation complète couvrant aussi l'Expression Écrite, les [formules Premium LlamaKusi](/tef-irn/pricing) s'adaptent à votre niveau et à votre échéance. Si vous avez déjà échoué à une session, notre guide sur [ce qu'il faut faire en cas d'échec](https://llamakusi.com/tef-irn/guides/que-faire-si-je-rate-tef-irn) détaille les solutions concrètes. Retrouvez l'ensemble des informations clés sur l'examen dans notre [guide complet TEF IRN 2026](https://llamakusi.com/tef-irn/guides/tout-comprendre-tef-irn).

## FAQ

**Le taux de réussite au TEF IRN est-il le même pour tous les centres d'examen ?**
Non, chaque centre peut afficher des résultats différents selon le profil de ses candidats et leur préparation en amont.

**Ai-je plus de chances si je vise seulement le niveau A2 ?**
Oui, statistiquement le niveau A2 affiche des taux de réussite par épreuve nettement plus élevés que le B1 ou le B2.

**Combien de fois puis-je repasser le TEF IRN en cas d'échec ?**
Il n'y a pas de limite officielle au nombre de tentatives, mais un délai minimum s'applique généralement entre deux inscriptions.

**L'Expression Écrite est-elle vraiment l'épreuve la plus difficile ?**
D'après les données disponibles, oui : c'est l'épreuve où le taux de réussite chute le plus nettement à mesure que le niveau visé augmente.

**Le niveau B1 est-il si différent du niveau au syndrome de l'imposteur que certains candidats ressentent ?**
Beaucoup de candidats B1 sous-estiment leur vrai niveau ; consultez notre guide sur [ce syndrome fréquent](https://llamakusi.com/tef-irn/guides/tef-irn-niveau-sous-estime) pour mieux évaluer vos chances réelles.
$CTA$ WHERE slug = 'taux-de-reussite-tef-irn';

UPDATE public.guides SET content = $CTA$# TCF IRN : les Délais d'Inscription à Respecter en 2026

Vous craignez de rater la date limite de votre dossier à cause du TCF IRN. En anticipant inscription, format choisi et délai de résultats, vous gardez le contrôle sur votre calendrier.

## Quel délai minimum respecter pour s'inscrire au TCF IRN ?

Comptez généralement entre **1 semaine et 1 mois** avant la date de session, selon le format choisi et le centre.

Chaque centre agréé par France Éducation International fixe sa propre date limite d'inscription, mais le format joue un rôle décisif : une session sur ordinateur se réserve souvent une semaine à l'avance, quand une session papier peut demander jusqu'à un mois. Un **délai obligatoire de 20 jours** s'impose aussi entre deux inscriptions au même test, utile à savoir si vous devez repasser l'épreuve.

Exemple : un candidat qui vise une session papier le 15 du mois doit généralement finaliser son inscription avant la mi-mois précédent, sous réserve de places disponibles dans son centre.

> Réservez votre session dès que vous connaissez votre date limite de dossier, même si vous ne vous sentez pas encore prêt : vous pourrez toujours vous préparer intensément d'ici l'examen.

## Combien de temps avant ma date limite de dossier dois-je passer le TCF IRN ?

Passez le test **2 à 3 mois** avant le dépôt prévu de votre dossier, pour absorber le délai de résultats et un éventuel repassage.

C'est la date de dépôt du dossier qui compte pour la validité de votre attestation, pas la date à laquelle l'instruction se termine ensuite. Pour les délais réels d'instruction d'un dossier de naturalisation en 2026, notre [guide dédié sur le délai d'instruction du dossier de naturalisation](https://llamakusi.com/examen-civique/guides/delai-instruction-dossier-naturalisation-2026) détaille les chiffres à jour, préfecture par préfecture.

Exemple : un candidat qui prévoit de déposer son dossier en septembre a intérêt à passer le TCF IRN dès juin, pour garder une marge en cas de résultat insuffisant.

> Notez la date de dépôt visée dans votre agenda, puis comptez à rebours : test, résultats, marge de sécurité.

## Le TCF IRN sur ordinateur ou sur papier : quelle différence pour vos délais ?

Le format ordinateur accélère presque tout : inscription plus tardive possible, résultats généralement disponibles en **environ 15 jours**, contre près de **4 semaines** pour le format papier.

Cette différence n'est pas anecdotique quand un dossier approche de sa date limite : choisir le format ordinateur, quand le centre le propose, peut faire gagner plusieurs semaines sur l'ensemble du calendrier. Le format papier reste cependant parfois plus disponible selon les centres et les périodes de l'année, notamment en été où les délais s'allongent pour les deux formats.

Un candidat pressé par une échéance de dossier proche privilégiera un centre proposant le format ordinateur, même si cela implique de s'éloigner un peu plus de son domicile.

> Demandez systématiquement au centre quel format est disponible à la date qui vous intéresse : les deux ne sont pas toujours proposés à chaque session.

## Combien de temps pour recevoir convocation et résultats ?

La convocation arrive par email quelques jours avant l'examen ; les résultats suivent sous **15 jours à 4 semaines** selon le format choisi.

France Éducation International délivre l'attestation après le délai de correction, plus long pour le format papier que pour le format ordinateur. Si vous ne recevez pas votre convocation quelques jours avant l'examen, vérifiez vos courriers indésirables avant de contacter le centre.

Exemple : « Bonjour, je n'ai pas reçu ma convocation, l'examen est dans deux jours » — un message que les centres reçoivent souvent, alors qu'elle se trouvait dans les spams.

> Ajoutez l'adresse email de votre centre à vos contacts dès l'inscription, pour éviter que la convocation atterrisse dans vos spams.

## Que faire si je rate le délai d'inscription ou ma date limite de dossier ?

Réinscrivez-vous à la prochaine session disponible et, si votre date limite de dossier est déjà dépassée, contactez votre préfecture pour connaître les options de report.

Rater une session n'est pas rédhibitoire : les centres organisent des sessions régulières, parfois hebdomadaires pour le format ordinateur. En revanche, un dossier préfecture incomplet à la date limite peut être classé sans suite.

Exemple : un candidat ayant raté sa session de mars se réinscrit immédiatement pour avril, tout en informant sa préfecture du délai supplémentaire nécessaire.

> En cas de doute sur votre date limite exacte, demandez une confirmation écrite à votre préfecture plutôt que de vous fier à une estimation.

## Combien coûte l'inscription et comment s'inscrire concrètement ?

Comptez entre **135€ et 210€** selon le centre et le format choisi, en inscription en ligne par carte bancaire.

Le tarif varie selon le format (l'ordinateur est parfois plus cher que le papier, ou l'inverse selon les centres), le jour choisi et la région. L'inscription se fait sur le site du centre agréé par France Éducation International : vous choisissez une session, réglez les frais, puis recevez votre convocation. Une inscription est généralement ferme et définitive : les frais restent acquis même en cas d'annulation, sauf justificatif valable (certificat médical, attestation employeur).

Exemple : un candidat qui compare deux centres voisins peut constater un écart de plusieurs dizaines d'euros pour la même session, uniquement selon le format proposé.

> Comparez 2 ou 3 centres avant de vous inscrire : les tarifs et les formats disponibles peuvent varier sensiblement d'une ville à l'autre.

## Comment LlamaKusi vous aide

LlamaKusi transforme cette préparation en méthode claire plutôt qu'en révisions dans le vide. Pendant que vous attendez votre session ou vos résultats, chaque minute compte pour progresser. À l'approche de l'examen, un accompagnement ciblé fait souvent la différence — comparez les [offres Premium LlamaKusi](/tef_irn/pricing). Pas besoin d'attendre l'examen pour vous entraîner : le [Coach IA Oral](/tef_irn/oral) est inclus dans votre abonnement LlamaKusi. Pour resituer ce point dans l'ensemble de votre dossier, consultez notre [guide complet Naturalisation & Démarches](https://llamakusi.com/tef-irn/guides/naturalisation-demarches-tef-irn-guide-complet).

## FAQ

**Le TCF IRN et le TEF IRN ont-ils les mêmes délais ?**
Les principes sont proches (convocation par email, validité 2 ans, délai de 20 jours entre deux tentatives), mais les délais exacts de résultats varient selon le format et le centre choisi.

**Puis-je repasser le TCF IRN si mon niveau n'est pas suffisant ?**
Oui, en respectant un délai minimum de 20 jours entre deux inscriptions au même test, et en payant à nouveau les frais d'inscription.

**Le format ordinateur est-il aussi reconnu que le format papier ?**
Oui, les deux formats donnent lieu à la même attestation, avec la même valeur devant les préfectures.

**Dois-je refaire tout le test si une seule épreuve est insuffisante ?**
Oui, les épreuves doivent être repassées ensemble : il n'est pas possible de ne repasser qu'une seule compétence.
$CTA$ WHERE slug = 'tcf-irn-inscription-demarche';

UPDATE public.guides SET content = $CTA$# Prix du TCF IRN en 2026 : Tarifs Réels par Centre et Aides Disponibles

Le TCF IRN n'a pas de prix national fixe. **Comptez entre 130 € et 210 €** selon le centre agréé choisi — voici comment éviter de payer plus que nécessaire.

## Combien coûte réellement le TCF IRN en 2026 ?

Comptez généralement entre **130 € et 210 €**, certains centres facturant jusqu'à 250 €.

France Éducation International (FEI), l'organisme qui délivre le TCF IRN, ne fixe aucun tarif national ni fourchette recommandée. Chaque centre agréé définit librement son prix d'inscription, ce qui explique des écarts significatifs pour un test pourtant strictement identique. Pour une vue d'ensemble complète des démarches TEF IRN/TCF IRN, notre [guide complet du TEF IRN](https://llamakusi.com/tef-irn/guides/tout-comprendre-tef-irn) répond aussi à de nombreuses questions pratiques.

Un centre parisien peut facturer 135 €, tandis qu'un centre en région facture 210 € pour exactement les mêmes 4 épreuves.

> Comparez le tarif de 2 ou 3 centres avant de vous inscrire : rien n'oblige à passer le test dans le centre le plus proche de chez vous, ni dans votre département de résidence.

## Pourquoi le prix varie-t-il autant d'un centre à l'autre ?

L'écart s'explique par le statut du centre (Alliance Française, université, organisme privé) et par ses propres charges de fonctionnement, pas par une différence de qualité du test.

Le TCF IRN étant strictement identique partout (mêmes épreuves, même barème, même organisme certificateur), le prix ne reflète aucune différence de contenu ou de reconnaissance. C'est uniquement une question de tarification propre à chaque centre.

Deux candidats qui passent le même test, l'un dans un centre à 135 €, l'autre à 210 €, reçoivent une attestation strictement équivalente aux yeux de la préfecture.

> Ne présumez jamais qu'un tarif plus élevé signifie un centre plus sérieux ou plus reconnu : la valeur de l'attestation ne dépend pas du prix payé.

## Le TCF IRN coûte-t-il plus cher ou moins cher que le TEF IRN ?

Les fourchettes de prix des deux tests se recoupent largement ; aucun des deux n'est systématiquement moins cher que l'autre.

Comme pour le TCF IRN, le TEF IRN n'a pas de tarif national fixe : chaque centre agréé par la CCI Paris Ile-de-France fixe librement son prix. Voir notre [guide complet sur le coût du TEF IRN](https://llamakusi.com/tef-irn/guides/cout-tef-irn-centre-examen) pour le détail des tarifs par centre.

Selon les centres consultés, un candidat peut trouver un TCF IRN moins cher qu'un TEF IRN dans sa ville, et l'inverse dans une autre ville.

> Comparez les deux tests dans votre zone géographique plutôt que de supposer que l'un est structurellement moins cher : la disponibilité des centres près de chez vous compte souvent plus que le nom du test.

## Combien coûte un repassage en cas d'échec ou d'attestation expirée ?

Le tarif d'un repassage est **identique au tarif initial** : il n'existe pas de réduction pour une nouvelle tentative.

Que ce soit après un score insuffisant ou après l'expiration de votre attestation (au bout de 2 ans, voir notre [guide sur la validité de l'attestation TCF IRN](https://llamakusi.com/tef-irn/guides/tcf-irn-validite-attestation-duree)), vous payez une nouvelle inscription complète. Un délai minimum s'applique aussi entre deux tentatives.

Un candidat qui échoue à l'épreuve d'expression orale doit repasser l'intégralité des 4 épreuves, pas seulement celle qui a posé problème, et payer le tarif complet à nouveau.

> Mieux vaut retarder légèrement votre inscription pour vous préparer sérieusement que de payer deux fois un test mal préparé.

## Quelles aides existent pour financer le TCF IRN ?

Plusieurs dispositifs peuvent réduire le coût réel : le CPF, l'OFII et France Travail selon votre situation.

Ces aides ne sont pas systématiques et dépendent de critères propres à chaque organisme (statut, parcours d'intégration, situation professionnelle). Il est recommandé de vérifier votre éligibilité directement auprès de chaque dispositif avant de payer l'inscription de votre poche.

Une personne suivant un parcours d'intégration OFII peut bénéficier d'une prise en charge partielle ou totale selon sa situation, quand une autre devra financer le test elle-même.

> Renseignez-vous sur ces aides avant de choisir votre centre : certains centres sont habitués à ces démarches de financement et vous accompagnent plus facilement dans les dossiers.

## Comment LlamaKusi vous aide

Chez LlamaKusi, l'objectif est simple : vous aider à réussir votre test dès la première tentative, pour ne jamais avoir à repayer une inscription. Envie de savoir où vous en êtes vraiment ? Testez le [Coach IA Oral](/tef_irn/oral) dans le cadre de votre abonnement LlamaKusi. Chaque profil est différent : les [formules Premium LlamaKusi](/tef_irn/pricing) s'adaptent à votre niveau et à votre échéance.

## FAQ

**Existe-t-il un tarif officiel unique pour le TCF IRN ?**
Non, chaque centre agréé fixe librement son prix, généralement entre 130 € et 210 €.

**Le prix le plus élevé garantit-il un meilleur centre ?**
Non, l'attestation délivrée est strictement identique quel que soit le prix payé.

**Puis-je bénéficier d'une réduction pour un repassage ?**
Non, le tarif d'un repassage est identique à celui d'une première inscription.

**Le CPF peut-il financer le TCF IRN ?**
Cela dépend de votre situation et du dispositif concerné : vérifiez votre éligibilité directement auprès de l'organisme avant de vous inscrire.
$CTA$ WHERE slug = 'tcf-irn-prix-tarif-2026';

UPDATE public.guides SET content = $CTA$# TCF IRN : Durée de Validité de l'Attestation en 2026 (et Différence avec le TEF IRN)

Vous avez passé le TCF IRN et vous vous demandez combien de temps votre attestation reste valable ? **Elle est valable 2 ans**, exactement comme celle du TEF IRN — la vraie question est de savoir jusqu'à quand.

## Combien de temps l'attestation TCF IRN est-elle valable ?

L'attestation TCF IRN est valable **2 ans** à compter de la date de délivrance des résultats, indiquée sur le document.

Cette durée est fixée par France Éducation International, l'organisme qui délivre le TCF IRN. Le point de départ est la date de délivrance des résultats, pas la date du passage de l'épreuve elle-même, ni la date de retrait physique de l'attestation auprès du centre. Pour une vue d'ensemble complète du TEF IRN, notre [guide complet du TEF IRN](https://llamakusi.com/tef-irn/guides/tout-comprendre-tef-irn) répond aussi à de nombreuses questions pratiques sur ces tests.

Un candidat qui passe le test en janvier 2026 et reçoit ses résultats début février voit sa validité courir à partir de février 2026, jusqu'à février 2028.

> Vérifiez la date précise inscrite sur votre attestation plutôt que de calculer depuis le jour du test : c'est cette date de délivrance des résultats qui fait foi.

## Cette durée est-elle différente de celle du TEF IRN ?

Non. **L'attestation TEF IRN est elle aussi valable 2 ans**, à compter de sa date d'édition — les deux tests ont exactement la même durée de validité.

TEF IRN et TCF IRN sont deux tests distincts (le premier délivré par la CCI Paris Ile-de-France, le second par France Éducation International), mais tous deux acceptés de façon équivalente par les préfectures pour les mêmes démarches. Sur ce point précis de la durée de validité, aucun des deux tests n'offre d'avantage sur l'autre.

Un candidat hésitant entre les deux tests uniquement pour la durée de validité de l'attestation peut choisir indifféremment l'un ou l'autre, ce critère ne les différencie pas. Notre [guide sur la validité de l'attestation TEF IRN](https://llamakusi.com/tef-irn/guides/tef-irn-validite-attestation-duree) détaille ce même point côté TEF, et notre [comparatif complet TEF IRN vs TCF IRN](https://llamakusi.com/tef-irn/guides/tef-irn-vs-tcf-irn) détaille les critères qui, eux, font vraiment la différence.

> Choisissez votre test sur d'autres critères (délai d'obtention des résultats, format sur ordinateur ou papier, centres disponibles près de chez vous), pas sur la durée de validité de l'attestation.

## La validité s'apprécie-t-elle au dépôt du dossier ou pendant toute l'instruction ?

La validité de l'attestation s'apprécie à la **date de dépôt du dossier complet**, pas pendant toute la durée de l'instruction qui suit.

Une fois le dossier déposé avec une attestation encore valide, une expiration ultérieure pendant l'instruction ne remet normalement pas en cause la demande en cours. Cette distinction est essentielle car l'instruction d'un dossier de naturalisation dure souvent plus longtemps que la validité elle-même de l'attestation.

Un candidat qui dépose son dossier avec une attestation TCF IRN valide jusqu'en juin 2026, alors que son instruction se prolonge jusqu'en 2027, n'a normalement pas besoin de repasser le test entre-temps.

> Consultez notre [guide sur le délai réel d'instruction d'un dossier de naturalisation](https://llamakusi.com/examen-civique/guides/delai-instruction-dossier-naturalisation-2026) : puisque l'attestation doit surtout être valide au dépôt, mieux vaut connaître ce délai avant de planifier votre calendrier.

## Que faire si votre attestation TCF IRN expire avant d'avoir déposé votre dossier ?

Il faut repasser le test avant le dépôt, car aucun dossier ne peut être déposé avec une attestation déjà expirée.

Il n'existe pas de limite au nombre de tentatives pour le TCF IRN, mais un délai minimum s'applique entre deux passages (20 jours au minimum selon France Éducation International, parfois 30 jours selon les centres). Mieux vaut anticiper cette contrainte plutôt que de la découvrir au moment de déposer un dossier avec une attestation périmée.

Un candidat qui constate que son attestation expire dans un mois, alors que son dossier n'est pas encore complet par ailleurs, a intérêt à repasser le test dès maintenant plutôt que d'attendre la dernière limite.

> Notez la date d'expiration de votre attestation dès sa réception et prévoyez de repasser le test un à deux mois avant le dépôt prévu de votre dossier, pour absorber les délais d'inscription et de résultats.

## Quelles sont les vraies différences entre le TCF IRN et le TEF IRN ?

La durée de validité étant identique, les vraies différences portent surtout sur l'organisme et le format de passation, pas sur le délai de carence entre deux tentatives.

Le TEF IRN est délivré par la CCI Paris Ile-de-France, le TCF IRN par France Éducation International. Le TCF IRN se passe le plus souvent entièrement sur ordinateur, avec des résultats généralement disponibles en quelques semaines. Le délai de carence entre deux tentatives, en revanche, est très proche pour les deux tests : un minimum officiel de 20 jours dans les deux cas, certains centres appliquant jusqu'à 30 jours pour le TCF IRN en pratique.

Un candidat qui a besoin de repasser rapidement un test après un score insuffisant peut donc choisir indifféremment l'un ou l'autre sur ce critère précis, la différence réelle étant minime.

> Le choix entre TEF IRN et TCF IRN dépend surtout de la disponibilité des centres près de chez vous et de vos préférences de format : les deux sont acceptés de façon strictement équivalente par les préfectures.

## Comment LlamaKusi vous aide

S'entraîner seul, sans retour sur ses erreurs, rend difficile de savoir si l'on est vraiment prêt à temps pour renouveler son attestation — c'est exactement ce que corrige LlamaKusi. Si cette échéance vous angoisse, le [Coach IA Oral](/tef_irn/oral) permet de s'entraîner en conditions réelles, avec votre abonnement. Les candidats qui visent un score élevé s'appuient souvent sur un accompagnement structuré — voyez ce que proposent les [offres LlamaKusi](/tef_irn/pricing).

## FAQ

**L'attestation TCF IRN expire-t-elle plus vite que celle du TEF IRN ?**
Non, les deux sont valables exactement 2 ans à compter de la délivrance des résultats.

**Puis-je déposer mon dossier avec une attestation qui expire le mois suivant ?**
Oui, tant qu'elle est valide au moment du dépôt du dossier complet, une expiration ultérieure pendant l'instruction ne pose normalement pas de problème.

**Combien de temps dois-je attendre pour repasser le TCF IRN ?**
Un minimum de 20 jours selon France Éducation International, parfois 30 jours selon les centres.

**Le TCF IRN est-il aussi reconnu que le TEF IRN par les préfectures ?**
Oui, les deux tests sont acceptés de façon équivalente pour les mêmes démarches (carte de séjour, carte de résident, naturalisation).
$CTA$ WHERE slug = 'tcf-irn-validite-attestation-duree';

UPDATE public.guides SET content = $CTA$# Micro-apprentissage TEF IRN : Réviser 5 Minutes par Jour avec Efficacité

Vous rentrez épuisé du travail, les enfants réclament votre attention, et le TEF IRN attend. Bonne nouvelle : **5 minutes par jour** suffisent à progresser durablement, sans bouleverser votre emploi du temps.

## Pourquoi 5 minutes par jour peuvent-elles suffire à préparer le TEF IRN ?

Oui, une routine courte et répétée bat une révision longue mais rare.

La mémorisation dépend surtout de la fréquence d'exposition, pas de la durée des séances. Sans répétition, vous oubliez plus de la moitié d'une information en une heure. Une micro-session quotidienne, réalisée avant votre café ou dans les transports, réactive le vocabulaire juste avant qu'il ne s'efface. Ce principe s'appelle la **répétition espacée**, connue depuis les travaux d'Ebbinghaus.

Exemple concret : chaque matin, vous révisez trois mots liés à un thème administratif, comme "convocation" ou "attestation".

> Fixez toujours le même horaire, café ou transport, pour transformer l'exercice en réflexe automatique.

## Quel exercice faire chaque matin pour progresser à l'oral du TEF IRN ?

Un exercice court d'expression orale enregistrée reste le plus rentable.

Chaque matin, choisissez une question type examen, par exemple "Décrivez votre quartier", et répondez à voix haute en **30 secondes**, sans écrire. Enregistrez-vous, puis réécoutez en identifiant une seule amélioration à corriger le lendemain. Cette boucle courte muscle la spontanéité, compétence centrale de l'épreuve d'Expression Orale.

Exemple concret : "Ce matin, mon quartier est calme, je vais au marché à pied."

> Ne cherchez jamais la phrase parfaite : la fluidité compte plus que la précision grammaticale.

## Comment organiser sa semaine avec seulement 5 minutes par jour ?

Alternez une compétence différente chaque jour de la semaine.

Répartir les 4 épreuves sur la semaine évite la lassitude et couvre l'ensemble du programme. Cette rotation limite l'oubli sans exiger de longues plages horaires libres.

Exemple concret d'organisation :
1. Lundi : 3 mots de vocabulaire administratif.
2. Mardi : 1 réponse orale de 30 secondes.
3. Mercredi : 1 court texte à lire et résumer.
4. Jeudi : 3 phrases d'expression écrite.
5. Vendredi : réécoute des enregistrements de la semaine.

> Notez votre routine sur votre téléphone pour ne jamais improviser le contenu du jour.

## La méthode des 5 minutes suffit-elle pour atteindre le niveau visé au TEF IRN ?

Elle prépare efficacement mais ne remplace pas un entraînement complet avant l'examen.

Depuis le 1er janvier 2026, la **loi n° 2024-42** du 26 janvier 2024 impose le niveau **A2** pour une première [carte de séjour pluriannuelle](https://www.service-public.gouv.fr/particuliers/vosdroits/F34501), **B1** pour la carte de résident, et **B2** pour la [naturalisation](https://www.service-public.gouv.fr/particuliers/vosdroits/F11926). Les 5 minutes quotidiennes construisent une base solide et une régularité durable. Mais à l'approche de l'examen, il reste indispensable de s'entraîner en conditions réelles, chronométrées, sur les 4 épreuves complètes.

Exemple concret : à 2 mois de l'examen, passez progressivement de 5 à 20 minutes par jour pour simuler le format réel.

> Augmentez la durée uniquement lorsque la routine de 5 minutes est devenue automatique, sans effort de motivation.

## Quelles erreurs éviter avec une méthode de micro-apprentissage ?

L'erreur la plus fréquente est de sauter des jours sans les rattraper.

Le micro-apprentissage fonctionne grâce à la régularité, pas à l'intensité ponctuelle. Sauter 3 jours puis faire 30 minutes d'un coup casse l'effet de répétition espacée et recrée la fatigue que vous cherchiez à éviter. Autre piège : viser plusieurs compétences en même temps dans une seule session de 5 minutes, ce qui dilue l'attention.

Exemple concret : mieux vaut réviser 3 mots parfaitement qu'essayer de lire un article entier en 5 minutes.

> Si vous manquez un jour, reprenez simplement le lendemain, sans session de rattrapage marathon.

## Comment LlamaKusi vous aide

Comment s'entraîner efficacement sans y passer des heures chaque jour ? En intégrant vos 5 minutes quotidiennes à un parcours structuré plutôt qu'à des révisions dispersées. LlamaKusi propose des exercices courts et ciblés, adaptés aux hyper-occupés, avec une correction immédiate qui rend chaque micro-session vraiment utile. Cette approche complète naturellement les routines détaillées dans notre [guide sur la révision au téléphone](https://llamakusi.com/tef-irn/guides/tef-irn-phone-tablette).

Envie de savoir où vous en êtes vraiment ? Testez le [Coach IA Oral](/tef-irn/oral) dans le cadre de votre abonnement LlamaKusi, pour votre session du matin.

À l'approche de l'examen, un accompagnement ciblé fait souvent la différence. Pour transformer ces 5 minutes en résultats mesurables, consultez aussi notre [planning de révision sur 30 jours](https://llamakusi.com/tef-irn/guides/comment-reviser-tef-irn-en-30-jours), puis comparez les [offres Premium LlamaKusi](/tef-irn/pricing). Notre [guide complet sur la méthode de révision](https://llamakusi.com/tef-irn/guides/methode-revision-tef-irn-guide-complet) regroupe toutes ces stratégies selon votre situation.

## FAQ

**5 minutes par jour, est-ce vraiment suffisant pour réussir le TEF IRN ?**
C'est suffisant pour construire une base régulière, mais un entraînement plus intensif reste nécessaire dans les semaines précédant l'examen.

**Que faire si je manque un jour de ma routine ?**
Reprenez simplement le lendemain. Ne cherchez jamais à rattraper plusieurs jours en une seule session longue.

**Quel moment de la journée choisir pour ma session de 5 minutes ?**
Le matin, avant le café ou pendant les transports, fonctionne bien car votre attention est encore disponible.

**Combien de temps avant de voir des progrès avec cette méthode ?**
Comptez généralement 4 à 6 semaines de régularité quotidienne avant de ressentir une vraie aisance sur le vocabulaire ciblé.
$CTA$ WHERE slug = 'tef-irn-5-minutes-matin';

UPDATE public.guides SET content = $CTA$# Annulation et Remboursement d'une Session TEF IRN en 2026 : Vos Droits Selon la CCI Paris IDF

Vous venez de payer votre inscription au TEF IRN et un imprévu survient. **Sauf absence justifiée**, la CCI Paris Ile-de-France ne rembourse pas les frais, mais un report reste parfois possible.

## Puis-je annuler mon inscription au TEF IRN et être remboursé ?

Non, en principe. **Toute inscription au TEF IRN est ferme et définitive**, selon les conditions officielles de la CCI Paris Ile-de-France. Le remboursement n'est prévu que si c'est la CCI elle-même qui annule votre session.

Cette règle s'applique à toutes les versions du test, y compris le TEF IRN. Elle vaut quel que soit le centre agréé où vous êtes inscrit — Alliance Française, CCI locale ou organisme partenaire — car c'est la CCI Paris Ile-de-France qui fixe la politique de remboursement, même si chaque centre gère le paiement localement. Pour une vue d'ensemble de toutes les étapes du TEF IRN, notre [guide complet du TEF IRN](https://llamakusi.com/tef-irn/guides/tout-comprendre-tef-irn) répond aux questions avant, pendant et après l'examen.

Un candidat inscrit dans un centre à l'étranger qui change simplement d'avis deux semaines avant sa session ne peut prétendre à aucun remboursement, sauf annulation décidée par le centre lui-même.

> Avant de payer, demandez au centre agréé sa politique exacte en cas d'imprévu : certains acceptent d'annuler sans frais dans les tout premiers jours suivant le paiement, à condition de les contacter très rapidement.

## Que se passe-t-il en cas d'absence non justifiée le jour de l'examen ?

Vous perdez la totalité des frais payés. **Aucun remboursement n'est possible**, ni par le centre agréé, ni par la CCI Paris Ile-de-France.

Cette règle vaut pour toute absence non justifiée ou tout abandon en cours de session, quelle que soit la raison invoquée après coup. Elle s'applique uniformément à tous les centres agréés dans le monde, car les conditions sont fixées de façon centralisée par la CCI Paris Ile-de-France, pas centre par centre.

Certains centres, comme des antennes de l'Alliance Française à l'étranger, précisent même explicitement au moment du paiement que les frais d'inscription sont **non remboursables**, avant même que la session n'ait lieu.

> Ne réservez votre créneau que lorsque vous êtes certain de votre disponibilité : un empêchement de dernière minute non justifié coûte l'intégralité du prix payé.

## Comment reporter votre session en cas d'absence justifiée ?

Une absence justifiée (maladie, urgence) et validée par la CCI Paris Ile-de-France permet un **report sur une autre session**, mais jamais un remboursement en argent.

Il faut transmettre un justificatif — certificat médical, convocation officielle — généralement via votre centre agréé, qui le fait suivre à la CCI Paris Ile-de-France. C'est la CCI qui valide ou non le caractère justifié de l'absence : le centre ne peut pas en décider seul. Une fois l'absence validée, votre inscription est reportée sur une session ultérieure, sans frais supplémentaires.

Un candidat hospitalisé la veille de son épreuve d'Expression Orale transmet son certificat médical à son centre agréé, qui le fait suivre à la CCI Paris Ile-de-France pour validation du report.

> Rassemblez votre justificatif le plus tôt possible et transmettez-le à votre centre sans attendre : plus vous agissez vite, plus le report a de chances d'être accepté avant que la session ne soit close administrativement.

## Les règles changent-elles selon le centre agréé où vous passez le TEF IRN ?

Les règles d'annulation et de remboursement sont **fixées par la CCI Paris Ile-de-France** et s'appliquent à tous les centres agréés, mais le prix payé, lui, varie d'un centre à l'autre.

Chaque centre agréé (Alliance Française, organisme partenaire) fixe librement ses frais d'inscription au TEF IRN. En revanche, la politique de non-remboursement en cas d'absence non justifiée, ou de report en cas d'absence validée, reste identique partout, car elle découle de la convention d'agrément signée avec la CCI Paris Ile-de-France. Pour comparer les tarifs pratiqués selon les centres, consultez notre [guide sur le coût du TEF IRN](https://llamakusi.com/tef-irn/guides/cout-tef-irn-centre-examen).

Deux candidats inscrits dans deux centres différents, l'un en France, l'autre à l'étranger, paient des tarifs différents mais sont soumis exactement aux mêmes conditions d'annulation.

> Contactez votre centre agréé avant de payer et demandez-lui sa réactivité habituelle pour transmettre un dossier de report à la CCI : certains centres accompagnent mieux leurs candidats que d'autres.

## Comment éviter de perdre votre inscription avant même la session ?

La meilleure protection reste d'anticiper : vérifiez votre disponibilité réelle avant de payer, et respectez le **délai de carence de 60 jours** entre deux passages d'une même épreuve.

Ce délai signifie que vous ne pouvez pas repasser deux fois la même épreuve du test d'évaluation de français en moins de 60 jours, toutes versions confondues — une inscription qui l'enfreint est automatiquement annulée. Consultez notre [guide sur les délais d'inscription au TEF IRN](https://llamakusi.com/tef-irn/guides/inscription-tef-irn-delais) pour planifier votre passage sans mauvaise surprise.

Un candidat qui s'inscrit à une session de rattrapage 40 jours après son dernier passage voit son inscription annulée d'office, sans possibilité de remboursement.

> Ne vous inscrivez que lorsque vous vous sentez réellement prêt : un entraînement sérieux en amont réduit fortement le risque d'un empêchement de dernière minute qui vous coûterait cher.

## Comment LlamaKusi vous aide

Chez LlamaKusi, l'objectif est simple : vous aider à arriver prêt dès votre première inscription, pour éviter tout report ou session ratée. Envie de savoir où vous en êtes vraiment ? Testez le [Coach IA Oral](/tef_irn/oral) dans le cadre de votre abonnement LlamaKusi, avant de payer votre place. Les candidats qui visent un score élevé s'appuient souvent sur un accompagnement structuré — voyez ce que proposent les [offres LlamaKusi](/tef_irn/pricing).

## FAQ

**Le TEF IRN est-il remboursable en cas de maladie ?**
Non, pas en argent. Si l'absence est justifiée par un certificat médical et validée par la CCI Paris Ile-de-France, votre session peut être reportée sur une autre date.

**Puis-je changer de date sans justificatif ?**
Non. Un changement de date sans motif validé par la CCI Paris Ile-de-France équivaut à une nouvelle inscription, donc à un nouveau paiement.

**Que faire si je me trompe de centre agréé au moment de m'inscrire ?**
Contactez immédiatement le centre concerné avant la session : une correction reste parfois possible, mais jamais après un paiement déjà traité comme définitif.

**Le délai de carence de 60 jours s'applique-t-il à toutes les épreuves ?**
Oui, il concerne toute nouvelle tentative sur une même épreuve du test d'évaluation de français, toutes versions confondues, y compris le TEF IRN.
$CTA$ WHERE slug = 'tef-irn-annulation-remboursement-session';

UPDATE public.guides SET content = $CTA$# Arnaque TEF IRN : Comment Vérifier un Centre Agréé en 2026

Vous cherchez un centre pour passer votre **TEF IRN** et vous redoutez de tomber sur une arnaque qui vous ferait perdre argent et temps. Un **centre agréé TEF IRN** se vérifie toujours en quelques minutes, avant tout paiement.

## Comment savoir si un centre TEF IRN est officiellement agréé ?

Un centre officiel apparaît obligatoirement dans [l'annuaire du Français des affaires](https://www.service-public.gouv.fr/particuliers/vosdroits/R52169), le site géré par la **CCI Paris Île-de-France**.

Ce portail recense tous les centres autorisés à faire passer le TEF IRN et à délivrer une attestation reconnue par les préfectures. Un centre absent de cet annuaire n'a aucune légitimité, même s'il affiche le mot « agréé » sur son site ou ses réseaux sociaux. Chaque centre référencé dispose d'un identifiant propre, rattaché directement à la CCI Paris Île-de-France.

Par exemple, avant de réserver, vous pouvez demander : « Êtes-vous bien référencé sur le site du Français des affaires ? » Un centre sérieux répond immédiatement et sans détour.

> Avant tout paiement, tapez le nom exact du centre dans l'annuaire officiel du Français des affaires pour confirmer son agrément.

## Existe-t-il vraiment des arnaques autour du TEF IRN ?

Oui, l'organisme officiel lui-même met en garde contre certaines officines qui promettent un résultat contre de fortes sommes d'argent.

Ces pratiques prennent plusieurs formes : promesse de niveau ou de score « garanti », frais cachés ajoutés après l'inscription, ou sessions organisées dans des lieux qui n'ont aucun lien avec un centre agréé. Le risque n'est pas seulement financier : une attestation obtenue hors circuit officiel peut être refusée en préfecture, ce qui retarde toute votre démarche de **naturalisation** ou de carte de résident.

Une annonce du type « Payez 800 euros, nous garantissons votre niveau B2 » doit immédiatement vous alerter : aucun centre officiel ne peut garantir un niveau, seule votre préparation détermine votre résultat.

> Aucun centre sérieux ne promet un score ou un niveau à l'avance : c'est le premier signal d'alerte à retenir.

## Quels signaux doivent vous alerter avant de vous inscrire ?

Trois signaux doivent systématiquement vous pousser à vérifier avant de payer :

- Une promesse de résultat ou de niveau garanti.
- Une absence totale du centre dans l'annuaire officiel du Français des affaires.
- Un paiement demandé par virement personnel ou en espèces, en dehors des canaux habituels du centre.

Un centre agréé fonctionne avec des tarifs affichés clairement et un mode de paiement traçable, jamais dans l'urgence ou sous pression commerciale.

Si un interlocuteur vous répond : « Inscrivez-vous aujourd'hui, il ne reste qu'une place et le tarif double demain », c'est une technique de pression classique, pas une pratique d'un centre officiel.

> Prenez toujours le temps de vérifier, même si l'interlocuteur insiste sur l'urgence de la décision.

## Que se passe-t-il si vous passez le test dans un lieu non reconnu ?

Votre attestation ne sera tout simplement pas acceptée par la préfecture, ce qui entraîne un rejet ou un ajournement de votre dossier.

Les préfectures vérifient systématiquement l'authenticité des attestations grâce à un code-barres et à un numéro d'identification unique, propres à chaque session organisée par un centre agréé. Une attestation issue d'un lieu non reconnu ne possède pas ces éléments et ne peut donc pas être validée, même si l'examen semblait sérieux sur place.

Un candidat qui découvre ce problème au moment du dépôt de son dossier doit repasser l'intégralité du test dans un centre officiel, ce qui coûte à nouveau du temps et de l'argent.

> Conservez toujours votre convocation et votre attestation : ce sont les preuves qui rassurent en cas de doute côté préfecture.

## Comment vérifier un centre en quelques minutes avant de payer ?

Trois étapes simples suffisent pour sécuriser votre choix :

1. Recherchez le nom exact du centre sur l'annuaire du Français des affaires (ou celui de France Éducation international pour le TCF IRN).
2. Comparez l'adresse et les tarifs affichés à ceux réellement annoncés par le centre.
3. Contactez directement le centre pour confirmer la session et poser vos questions avant de régler quoi que ce soit.

Cette vérification prend moins de dix minutes et élimine la quasi-totalité du risque d'arnaque.

## Comment LlamaKusi vous aide

Une fois votre centre sécurisé, la question suivante est de savoir comment vous préparer sans stress. Si cette étape vous angoisse encore, le [Coach IA Oral](/tef-irn/oral) permet de s'entraîner en conditions réelles, dans le cadre de votre abonnement LlamaKusi. Chaque profil est différent : les [formules Premium LlamaKusi](/tef-irn/pricing) s'adaptent à votre niveau et à votre échéance, avec un accompagnement transparent, sans promesse irréaliste. Comme pour le choix de votre centre, LlamaKusi ne vous promet jamais un score : seule une vraie préparation fait la différence. Vous pouvez également consulter notre guide sur le [coût du TEF IRN et les centres agréés](https://llamakusi.com/tef-irn/guides/cout-tef-irn-centre-examen) pour comparer les tarifs en toute transparence. Pour resituer ce point dans l'ensemble de l'examen, notre [guide complet TEF IRN](https://llamakusi.com/tef-irn/guides/tout-comprendre-tef-irn) reste la référence.

## FAQ

**Comment vérifier qu'un centre TEF IRN est bien agréé ?**
Consultez l'annuaire officiel du Français des affaires et recherchez le nom exact du centre avant toute inscription.

**Un centre peut-il me garantir un score au TEF IRN ?**
Non, aucun centre officiel ne peut garantir un niveau ou un score : c'est un signal d'arnaque à repérer immédiatement.

**Que faire si mon attestation est refusée en préfecture ?**
Vérifiez d'abord si le centre où vous avez passé le test figure dans l'annuaire officiel ; sinon, vous devrez repasser le test dans un centre agréé.

**Le TCF IRN a-t-il aussi un annuaire officiel de centres ?**
Oui, [France Éducation international publie sa propre carte des centres agréés](https://www.france-education-international.fr/centres-d-examen/carte) pour le TCF IRN, distincte de celle du TEF IRN — voir notre comparatif [TEF IRN vs TCF IRN](https://llamakusi.com/tef-irn/guides/tef-irn-vs-tcf-irn) pour bien choisir.

**Dois-je me méfier des centres qui exigent un paiement en espèces uniquement ?**
Oui, un mode de paiement non traçable, imposé sans alternative, fait partie des signaux à vérifier avant de vous inscrire.
$CTA$ WHERE slug = 'tef-irn-arnaque-centre-agree';

UPDATE public.guides SET content = $CTA$# Carte de Séjour 2026 : Réussir le TEF IRN Niveau A2

Vous devez justifier d'un niveau de français pour votre carte de séjour et vous ne savez pas par où commencer ? Le **niveau A2** suffit, et ce guide vous montre un parcours simple pour y arriver.

## Quel niveau de français faut-il pour obtenir une carte de séjour pluriannuelle en 2026 ?

Depuis le **1er janvier 2026**, le niveau **A2** du CECRL est exigé pour toute première demande de carte de séjour pluriannuelle.

Cette règle découle du **décret n° 2025-647 du 15 juillet 2025**, qui fixe les nouveaux articles R413-15 et R433-5 du CESEDA ([Légifrance](https://www.legifrance.gouv.fr/jorf/id/JORFTEXT000051900489)). Elle concerne les ressortissants étrangers non européens de moins de 65 ans qui déposent une première demande. Les cartes portant la mention "protection subsidiaire" ne sont pas concernées, tout comme les personnes de plus de 65 ans, qui restent dispensées de cette obligation linguistique.

**Exemple concret** : à l'oral, l'examinateur peut demander « Parlez-moi de votre travail et de votre famille. » — une réponse simple avec du vocabulaire courant suffit pour ce niveau.

> Le niveau A2 reste un niveau élémentaire : comprendre des phrases isolées sur des sujets familiers, pas un français parfait.

## Quelles sont les 4 épreuves du TEF IRN à réussir pour le niveau A2 ?

Le TEF IRN évalue quatre compétences distinctes, chacune notée séparément : compréhension orale, compréhension écrite, expression orale et expression écrite.

Pour obtenir le niveau A2 global, il faut atteindre ce niveau dans les quatre épreuves, pas seulement en moyenne. L'examen dure au total environ **1h30** et se déroule en présentiel, dans un centre agréé, avec un contrôle d'identité avant chaque épreuve. L'expression orale reste la seule épreuve face à un examinateur ; les trois autres se passent sur ordinateur.

**Exemple concret** : en compréhension orale, vous entendrez une annonce simple (horaires de bus, message vocal) suivie d'une question à choix multiple.

> Travaillez les quatre épreuves en parallèle : un score faible dans une seule suffit à empêcher l'obtention du niveau A2 global.

## Quels diplômes ou certifications remplacent le TEF IRN pour justifier le niveau A2 ?

Le TEF IRN n'est pas obligatoire : plusieurs diplômes officiels suffisent pour justifier votre niveau A2 sans passer d'examen.

L'**arrêté du 22 décembre 2025** fixe la liste des justificatifs acceptés ([service-public.fr](https://www.service-public.gouv.fr/particuliers/vosdroits/F34501)) : le diplôme national du brevet, tout diplôme d'État de niveau 3 ou plus du répertoire national des certifications professionnelles (CAP, bac, licence...), ou une certification linguistique reconnue comme le TCF IRN ou le DELF A2. Le DELF a l'avantage d'être valable à vie, contrairement au TEF ou au TCF, valables deux ans.

**Exemple concret** : un candidat titulaire d'un CAP obtenu en France n'a besoin d'aucun autre justificatif linguistique pour sa carte de séjour.

> Vérifiez d'abord si un diplôme que vous possédez déjà suffit : cela vous évite de passer un examen inutile.

## Comment se déroule concrètement le jour de l'examen TEF IRN pour le niveau A2 ?

L'examen se déroule en une seule session, dans un centre agréé, avec une surveillance stricte contre la fraude.

Vous passez d'abord la compréhension écrite et la compréhension orale sur ordinateur, puis l'expression écrite, également sur ordinateur. L'expression orale se déroule en face d'un examinateur, sous forme de dialogue guidé sur des sujets familiers. Pour approfondir chaque étape, notre [guide sur le déroulé complet de l'examen TEF IRN](https://llamakusi.com/tef-irn/guides/comment-se-deroule-examen-tef-irn) détaille le jour J minute par minute.

**Exemple concret** : à l'oral, l'examinateur peut vous montrer une image et vous demander de décrire une situation du quotidien.

> Arrivez avec votre pièce d'identité originale : sans elle, l'accès à la salle d'examen est refusé.

## Quelles pièces fournir à la préfecture avec votre attestation de niveau A2 ?

L'attestation de niveau A2, valable **deux ans**, doit être présentée avec une pièce d'identité en cours de validité.

Depuis 2026, la carte de séjour pluriannuelle nécessite aussi la réussite de l'**examen civique**, une démarche distincte du niveau de langue. Ces deux justificatifs s'ajoutent au dossier habituel de demande de titre de séjour, sans remplacer les autres pièces déjà exigées par votre préfecture.

**Exemple concret** : présenter une attestation TEF IRN de 2024 reste valable en 2026, tant que les deux ans ne sont pas dépassés.

> Anticipez votre inscription à l'examen : les délais d'attente pour une session peuvent atteindre plusieurs mois selon les centres.

## Combien de temps prévoir pour préparer le niveau A2 du TEF IRN ?

Quelques semaines de préparation régulière suffisent généralement pour le niveau A2, nettement moins que pour le B1 ou le B2.

Le niveau A2 porte sur des situations familières et un vocabulaire courant, plus accessible qu'un niveau intermédiaire. Un entraînement quotidien court, centré sur les quatre épreuves, reste plus efficace que de longues sessions occasionnelles. Notre [planning de révision en 30 jours](https://llamakusi.com/tef-irn/guides/comment-reviser-tef-irn-en-30-jours) propose une organisation réaliste, même en travaillant à temps plein.

**Exemple concret** : 20 minutes par jour pendant trois semaines suffisent souvent pour se sentir prêt au niveau A2.

> À l'approche de votre rendez-vous en préfecture, un accompagnement ciblé fait souvent la différence — comparez les [offres Premium LlamaKusi](/tef-irn/pricing) pour préparer sereinement votre examen.

## Comment LlamaKusi vous aide

S'entraîner seul, sans retour, rend difficile de savoir où l'on progresse réellement — c'est exactement ce que corrige LlamaKusi. La plateforme propose un parcours adapté spécifiquement au niveau A2, sans vous surcharger avec des exercices trop avancés. Pas besoin d'attendre l'examen pour vous entraîner : le [Coach IA Oral](/tef-irn/oral) est inclus dans votre abonnement LlamaKusi. Pour une vue d'ensemble complète du TEF IRN (épreuves, niveaux, déroulement), consultez notre [guide complet 2026](https://llamakusi.com/tef-irn/guides/tout-comprendre-tef-irn).

## FAQ

**Le niveau A2 est-il suffisant pour tous les titres de séjour ?**
Non, seule la première carte de séjour pluriannuelle demande le niveau A2 ; la carte de résident exige le B1 et la naturalisation le B2.

**Que se passe-t-il si je n'atteins pas le niveau A2 dans une seule épreuve ?**
Le niveau global n'est pas validé : il faut représenter l'examen en visant les quatre épreuves à nouveau.

**Le TEF IRN est-il obligatoire pour justifier le niveau A2 ?**
Non, un diplôme reconnu comme le brevet ou un diplôme RNCP de niveau 3 ou plus peut suffire, sans passer d'examen.

**Combien de temps l'attestation TEF IRN reste-t-elle valable ?**
Elle est valable **deux ans** à partir de la date de passage de l'examen.
$CTA$ WHERE slug = 'tef-irn-carte-sejour-A2';

UPDATE public.guides SET content = $CTA$# Financer son TEF IRN 2026 : CPF, Aides et Reste à Charge

Vous redoutez le prix du TEF IRN et de sa préparation ? Bonne nouvelle : plusieurs solutions existent en 2026 pour réduire, voire annuler, ce coût grâce au CPF et aux aides financières disponibles.

## Combien coûte réellement le TEF IRN en 2026 ?

Comptez généralement entre **170 € et 200 €** pour l'examen seul, auxquels s'ajoutent parfois des frais de préparation ou de déplacement.

Le tarif varie selon le centre agréé et la version passée : les 4 épreuves complètes du TEF IRN se situent souvent entre 170 € et 320 €, tandis qu'une version orientée uniquement naturalisation reste généralement moins chère. À ce montant peuvent s'ajouter une attestation supplémentaire ou des frais de déplacement si le centre choisi est éloigné de votre domicile.

Un candidat à Lyon peut par exemple payer 185 € pour son inscription, contre 220 € dans un centre parisien proposant des créneaux plus flexibles.

> Comparez toujours 2 ou 3 centres agréés proches de chez vous : les tarifs et les délais de convocation varient sensiblement d'un centre à l'autre. Pour aller plus loin, consultez notre guide sur le [coût du TEF IRN et les centres agréés](https://llamakusi.com/tef-irn/guides/cout-tef-irn-centre-examen).

## Peut-on financer le TEF IRN avec son CPF en 2026 ?

Oui : le **[TEF IRN est reconnu par France Compétences depuis octobre 2024](https://www.francecompetences.fr/recherche/rs/6775/)** et reste éligible au CPF en 2026, à condition que le centre choisi soit bien référencé.

Votre Compte Personnel de Formation peut couvrir à la fois la préparation et la passation du test, dans la limite de vos droits acquis. Il vous suffit de créer un dossier sur Mon Compte Formation, de rechercher "TEF IRN", puis de sélectionner un centre partenaire officiellement référencé par France Compétences.

Un futur candidat peut par exemple demander à son centre : "Puis-je payer mon TEF IRN avec mon CPF ?" et obtenir une réponse positive, à condition que le centre confirme son numéro d'enregistrement au Répertoire Spécifique.

> Vérifiez systématiquement le numéro d'enregistrement RS de la certification avant de valider votre dossier : un centre qui ne peut pas vous le donner n'est probablement pas éligible au CPF.

## Le CPF suffit-il à tout payer, ou reste-t-il des frais à ma charge ?

Non : depuis le **2 avril 2026**, une [participation forfaitaire obligatoire de 150 €](https://www.service-public.gouv.fr/particuliers/actualites/A17364) s'applique à chaque dossier CPF, sauf exonération.

Ce reste à charge, introduit en 2024 puis revalorisé plusieurs fois depuis, s'ajoute au montant couvert par vos droits CPF. Il est dû une seule fois par dossier de formation, pas par session d'examen, et ne concerne pas les personnes exonérées (voir la section suivante).

Une candidate dont le CPF couvre 190 € de préparation devra tout de même régler les 150 € de participation avant que son inscription soit validée.

> Ce montant de 150 € est fixé pour l'année 2026 uniquement et peut évoluer en 2027 : vérifiez toujours le montant exact affiché sur Mon Compte Formation au moment de votre inscription.

## Quelles aides existent si je suis demandeur d'emploi ?

Les demandeurs d'emploi inscrits à France Travail sont **automatiquement exonérés du reste à charge CPF** et peuvent solliciter l'Aide Individuelle à la Formation (AIF).

L'AIF complète le financement lorsque le CPF ne suffit pas, à condition que votre projet soit validé au préalable par un conseiller France Travail. Une aide à la mobilité peut également couvrir vos frais de déplacement si le centre d'examen se trouve loin de votre domicile.

Un demandeur d'emploi dont les droits CPF sont insuffisants peut ainsi demander un abondement complémentaire directement depuis Mon Compte Formation, sans avancer de frais.

> Validez toujours votre projet de formation avec votre conseiller France Travail avant de vous inscrire : l'AIF n'est accordée qu'après cette étape.

## Mon employeur ou ma collectivité peuvent-ils m'aider à payer le test ?

Oui : un cofinancement de votre employeur ou d'une collectivité territoriale peut couvrir tout ou partie du coût, y compris la participation obligatoire de 150 €.

Certaines entreprises acceptent de financer la préparation lorsque la progression en français a un intérêt professionnel pour le poste occupé. Les conseils régionaux et certaines mairies proposent aussi ponctuellement des aides pour les démarches d'intégration ou de naturalisation, souvent méconnues des candidats.

Un salarié dont le projet de naturalisation est soutenu par son employeur peut ainsi voir sa participation CPF entièrement prise en charge dans le cadre d'un abondement.

> Renseignez-vous auprès de votre mairie ou de votre conseil régional : certaines aides à l'intégration ne sont jamais mentionnées par les centres d'examen eux-mêmes.

## Comment éviter de payer deux fois si j'échoue au test ?

En vous préparant sérieusement avant l'inscription : un échec implique de repayer l'intégralité des frais pour repasser le TEF IRN.

Contrairement à un abonnement de révision, l'examen ne prévoit aucun tarif réduit en cas de repassage. Mieux vaut donc investir dans une préparation efficace avant de mobiliser son CPF, plutôt que de risquer une deuxième inscription complète quelques mois plus tard.

Un candidat pas assez entraîné sur l'expression orale peut échouer d'un point et devoir attendre la prochaine session en repayant la totalité du tarif. Si cela vous arrive malgré tout, notre guide sur [que faire en cas d'échec au TEF IRN](https://llamakusi.com/tef-irn/guides/que-faire-si-je-rate-tef-irn) détaille vos options.

> Faites un test blanc avant de vous inscrire officiellement : il vaut souvent mieux repousser son inscription de quelques semaines que de payer deux fois le prix de l'examen.

## Comment LlamaKusi vous aide

Comment s'entraîner efficacement sans multiplier les dépenses de préparation ? Plutôt que d'investir dans des cours particuliers coûteux, testez le [Coach IA Oral LlamaKusi](/tef-irn/oral), inclus dans votre abonnement, pour évaluer votre niveau réel avant de mobiliser votre CPF. Cette pratique régulière réduit le risque d'échec, et donc le risque de payer deux fois l'examen. Pour un accompagnement plus complet, les candidats visant un score élevé s'appuient souvent sur un suivi structuré — découvrez ce que proposent les [offres LlamaKusi](/tef-irn/pricing). Si vous démarrez tout juste votre préparation, notre [guide complet sur le TEF IRN](https://llamakusi.com/tef-irn/guides/tout-comprendre-tef-irn) reprend l'essentiel : épreuves, niveaux et déroulement du jour J.

## FAQ

**Le TEF IRN est-il vraiment éligible au CPF en 2026 ?**
Oui, depuis octobre 2024, et cela reste valable en 2026 pour les centres référencés par France Compétences.

**Combien coûte la participation obligatoire CPF en 2026 ?**
150 € par dossier depuis le 2 avril 2026, sauf pour les demandeurs d'emploi qui en sont exonérés.

**Puis-je cumuler plusieurs aides pour financer mon TEF IRN ?**
Oui, le CPF, une aide employeur et des dispositifs locaux peuvent souvent se cumuler selon votre situation.

**Que faire si je n'ai pas assez de droits CPF ?**
Solliciter un abondement complémentaire auprès de France Travail ou de votre employeur avant de valider votre inscription.

**Les frais d'examen sont-ils remboursés en cas d'échec ?**
Non, les frais ne sont jamais remboursés : seule une nouvelle inscription payante permet de repasser le test.
$CTA$ WHERE slug = 'tef-irn-comment-financer';

UPDATE public.guides SET content = $CTA$# TEF IRN Conjoint Français 2026 : Niveaux, Démarches et Préparation à Deux

Vous partagez votre vie avec un Français, mais l'administration exige un test de langue pour votre titre de séjour. Bonne nouvelle : le TEF IRN reste accessible même en partant de zéro.

## Le conjoint de Français doit-il passer le TEF IRN pour son titre de séjour ?

Oui, dans la majorité des cas : depuis le 1er janvier 2026, une première carte de séjour "conjoint de Français" exige une certification officielle de français, comme le **TEF IRN**.

La loi du 26 janvier 2024 et [ses décrets d'application du 15 juillet 2025](https://www.legifrance.gouv.fr/jorf/id/JORFTEXT000051900489) ont généralisé cette obligation aux titres "vie privée et familiale", qui incluent le motif conjoint de Français. Seule la première demande est concernée : un renouvellement de carte de séjour ne nécessite pas de repasser le test. Le TEF IRN, délivré par la CCI Paris Île-de-France, fait partie des certifications reconnues par le ministère de l'Intérieur, au même titre que le TCF IRN ou le DELF.

Un candidat marié depuis huit mois qui dépose sa première demande de carte pluriannuelle devra donc joindre une attestation TEF IRN valide à son dossier ANEF.

> Vérifiez la date exacte de dépôt de votre dossier : les demandes déposées avant le 1er janvier 2026 ne sont pas concernées par cette nouvelle obligation.

## Quel niveau de français faut-il pour la carte de séjour conjoint de Français en 2026 ?

Le **niveau A2** est exigé pour la première carte de séjour pluriannuelle, et le **niveau B1** pour la carte de résident de 10 ans obtenue après trois ans de mariage, [comme le précise service-public.fr](https://www.service-public.gouv.fr/particuliers/vosdroits/F34501).

Ces niveaux doivent être atteints dans les quatre compétences : compréhension orale, compréhension écrite, expression orale et expression écrite. Au TEF IRN, le niveau A2 correspond à un score d'au moins 200 points sur trois épreuves et 167 sur la moins bonne ; le niveau B1 demande respectivement 300 et 267 points. Ce rehaussement, issu du décret n°2025-647 du 15 juillet 2025, représente un saut de deux niveaux par rapport aux règles applicables avant 2026.

Une candidate qui obtient 210 points en compréhension orale mais seulement 150 en expression écrite n'atteint donc pas le niveau A2 sur l'ensemble du test.

> Ne visez pas seulement la moyenne : un score trop faible dans une seule épreuve peut faire échouer tout le niveau demandé.

## Existe-t-il des dispenses de TEF IRN pour les conjoints de Français ?

Oui, plusieurs situations dispensent du test, mais elles ne sont jamais automatiques : c'est toujours la préfecture qui les accorde.

Sont notamment concernés les titulaires d'un diplôme français de niveau RNCP 3 ou plus, les personnes ayant suivi trois ans de scolarité secondaire ou un an d'études supérieures en France, les ressortissants de pays où le français est langue officielle, ainsi que les personnes en situation de handicap ou de santé déficiente sur certificat médical. Les personnes de 65 ans ou plus au moment de la demande bénéficient également d'une exemption.

Un conjoint originaire du Sénégal, où le français est langue officielle, pourra présenter cette situation à sa préfecture plutôt que de passer le test.

> Ne présumez jamais d'une dispense : demandez une confirmation écrite à votre préfecture avant de renoncer à vous inscrire au test.

## Comment se déroule l'épreuve du TEF IRN pour un conjoint de Français ?

Le TEF IRN comprend quatre épreuves passées le même jour, dans un centre agréé par la CCI Paris Île-de-France.

Compréhension orale et écrite se déroulent sous forme de QCM collectifs, tandis que l'expression orale se fait en face-à-face avec un examinateur, autour de mises en situation de la vie courante. L'expression écrite demande de rédiger deux textes courts. Comptez généralement quinze jours ouvrés après la session pour recevoir votre attestation, valable deux ans. Notre guide sur les [délais d'inscription au TEF IRN](https://llamakusi.com/tef-irn/guides/inscription-tef-irn-delais) détaille comment anticiper au mieux votre réservation.

Lors de l'épreuve orale, l'examinateur peut demander : « Décrivez votre installation en France depuis votre mariage » — une situation typique du quotidien d'un conjoint étranger.

> Réservez votre session six à huit semaines à l'avance : les créneaux se saturent vite dans les grandes villes.

## Comment s'organiser à deux pour préparer le TEF IRN sans que ça pèse sur le couple ?

La préparation avance mieux quand elle devient un projet partagé plutôt qu'une charge individuelle.

Fixer des créneaux courts et réguliers, plutôt que de longues sessions isolées, aide à tenir la distance sans tension. Le conjoint français peut jouer un rôle actif : reformuler une phrase, proposer un sujet de conversation, ou simplement écouter s'entraîner à l'oral. Cette implication rassure autant qu'elle prépare, car le TEF IRN évalue justement la capacité à échanger dans des situations de la vie quotidienne. Pas besoin d'attendre le jour J pour vous entraîner à deux : le [Coach IA Oral](/tef-irn/oral) est inclus dans votre abonnement LlamaKusi, en complément de vos échanges en couple.

Un couple peut par exemple consacrer quinze minutes chaque soir à discuter uniquement en français d'un sujet du jour, en conditions proches de l'épreuve orale.

> Évitez de transformer chaque erreur en source de tension : notez-les à froid, hors des moments de vie commune.

## Que faire si je n'obtiens pas le niveau demandé avant le dépôt du dossier ?

Vous pouvez repasser le TEF IRN autant de fois que nécessaire, sans limite de tentatives, mais un délai minimal s'applique généralement entre deux sessions.

En attendant d'atteindre le niveau requis, il reste possible de renouveler une carte de séjour temporaire d'un an, le temps de progresser. Certaines préfectures acceptent un dossier accompagné d'un engagement de formation en cours. Un refus fondé uniquement sur le niveau de français peut, dans certains cas, être contesté devant le tribunal administratif avec l'aide d'un avocat. Si votre situation touche aussi un retour d'expatriation en France, notre guide dédié aux [Français expatriés](https://llamakusi.com/tef-irn/guides/tef-irn-francais-expats) complète utilement cette page.

Un candidat qui obtient 190 points en compréhension écrite peut retenter la session suivante en concentrant sa préparation sur cette seule épreuve.

> Gardez toutes vos attestations, même celles sous le niveau requis : elles montrent une démarche active en cas de contestation.

## Comment LlamaKusi vous aide

S'entraîner seul, sans retour extérieur, rend difficile de savoir où l'on progresse réellement — c'est exactement ce que corrige LlamaKusi. La plateforme propose un parcours adapté au niveau A2 ou B1 visé, avec une correction immédiate de l'expression orale et écrite. Chaque conjoint avance à son rythme : les [offres Premium LlamaKusi](/tef-irn/pricing) s'adaptent à votre niveau de départ et à l'échéance de votre dossier préfectoral. Pour une vue d'ensemble du dossier administratif, consultez le [guide complet Naturalisation & Démarches](https://llamakusi.com/tef-irn/guides/naturalisation-demarches-tef-irn-guide-complet).

## FAQ

**Le TEF IRN est-il obligatoire pour renouveler ma carte de séjour conjoint de Français ?**
Non, seule la première demande de carte pluriannuelle ou de carte de résident est concernée.

**Combien coûte le TEF IRN ?**
Comptez généralement entre 100 et 200 € selon le centre d'examen choisi.

**Le TEF IRN peut-il être financé par le CPF ?**
Oui, à condition que l'organisme de formation associé soit certifié Qualiopi.

**Quelle différence entre le TEF IRN et le TCF IRN pour un conjoint de Français ?**
Les deux sont reconnus par les préfectures et évaluent les mêmes niveaux ; le choix dépend surtout des sessions disponibles près de chez vous.

**Que se passe-t-il en cas de rupture de la vie commune pendant la préparation ?**
Le dossier de titre de séjour peut être affecté ; ce point relève d'un conseil juridique, pas de la préparation linguistique.
$CTA$ WHERE slug = 'tef-irn-conjoint-francais';

UPDATE public.guides SET content = $CTA$# Laïcité et Valeurs Républicaines : Ce qu'il Faut Dire à l'Oral du TEF IRN

Vous redoutez la question sur la laïcité posée pendant l'entretien de naturalisation ? En 2026, quelques repères clairs suffisent pour répondre avec assurance et convaincre l'examinateur.

## Qu'est-ce que la laïcité et pourquoi revient-elle si souvent à l'oral ?

La **laïcité** est le principe de séparation entre l'État et les religions, garanti depuis la [loi du 9 décembre 1905](https://www.legifrance.gouv.fr/loda/id/JORFTEXT000000508749). Elle revient presque systématiquement en entretien de naturalisation.

Ce principe signifie que l'État reste neutre face à toutes les convictions religieuses ou non religieuses. Chacun garde la liberté de croire, de ne pas croire, ou de changer de religion. L'agent de préfecture vérifie que vous comprenez cette notion, pas que vous récitez une définition apprise par cœur. C'est un des piliers de l'assimilation évaluée au titre de l'**article 21-24 du Code civil**.

*Exemple* : l'examinateur demande « Que signifie la laïcité pour vous ? ». Une réponse solide : « L'État reste neutre, chacun croit ou ne croit pas librement, sans que sa religion change ses droits. »

> Ne citez jamais uniquement la devise « Liberté, Égalité, Fraternité » : ajoutez toujours la laïcité, souvent oubliée par les candidats et pourtant essentielle.

## Quelles valeurs de la République faut-il savoir expliquer clairement ?

Au-delà de la devise, l'agent attend une compréhension de la **liberté**, l'**égalité**, la **fraternité**, la **laïcité**, et l'**égalité entre les femmes et les hommes**.

Chaque valeur doit pouvoir s'expliquer en une phrase simple et personnelle, pas comme un cours d'instruction civique. La liberté couvre le droit de penser, de parler et de voter. L'égalité signifie les mêmes droits devant la loi, sans distinction d'origine ou de religion. Ces notions sont aussi reprises dans le **Contrat d'engagement républicain** signé par tout nouveau naturalisé, aux côtés des autres [codes culturels](https://llamakusi.com/tef-irn/guides/codes-culturels-france) attendus lors de l'entretien.

*Exemple* : « Pour moi, l'égalité veut dire qu'un homme et une femme ont le même salaire pour le même travail. »

> Préparez une phrase courte et personnelle par valeur plutôt qu'un long discours mémorisé, qui sonne toujours artificiel à l'oral.

## Comment répondre si l'agent aborde un sujet de société sensible ?

Restez factuel : rattachez votre réponse à un principe républicain plutôt qu'à une opinion personnelle tranchée sur un sujet polémique.

Depuis la circulaire Retailleau, les agents interrogent plus souvent sur des sujets comme la laïcité à l'école, l'égalité femmes-hommes ou la liberté d'expression. L'objectif n'est pas d'obtenir un avis politique, mais de vérifier que vous comprenez le cadre légal et que vous savez l'appliquer à une situation concrète. Une hésitation n'est pas éliminatoire si la réponse reste cohérente.

*Exemple* : « Pourquoi les signes religieux visibles sont-ils interdits à l'école publique ? » — « La [loi de 2004](https://www.legifrance.gouv.fr/jorf/id/JORFTEXT000000417977) protège la neutralité de l'école, un lieu commun à tous les élèves. »

> Une réponse honnête et posée vaut toujours mieux qu'une réponse récitée mécaniquement : l'agent détecte facilement ce qui n'est pas compris.

## Quelles erreurs faut-il éviter en parlant de laïcité ou d'égalité ?

L'erreur la plus fréquente est de confondre laïcité et interdiction de la religion, alors qu'elle protège au contraire la liberté de conscience de chacun.

D'autres pièges reviennent souvent : donner une opinion politique tranchée, contredire un élément déjà présent dans le dossier, ou répondre par un simple « je ne sais pas » sans reformuler. Envie de savoir où vous en êtes vraiment sur ces sujets ? Testez le [Coach IA Oral](/tef-irn/oral) dans le cadre de votre abonnement LlamaKusi, pour vous entraîner sur des mises en situation réalistes.

*Exemple* : plutôt que « la laïcité interdit la religion », dire « la laïcité garantit la liberté de croire ou de ne pas croire, sans privilégier aucun culte ».

> Si une question vous surprend, demandez une reformulation plutôt que de répondre au hasard : c'est accepté et souvent valorisé.

## Comment le TEF IRN entraîne-t-il à ce type d'échange à l'oral ?

L'épreuve d'**Expression Orale du TEF IRN** demande déjà de défendre un point de vue argumenté, un entraînement direct utile pour l'entretien de naturalisation.

La Section B de l'oral, en particulier, évalue votre capacité à structurer une opinion sur un sujet de société en français, exactement le type d'exercice attendu face à l'agent de préfecture. Notre [guide sur la méthode PRAC pour l'Expression Orale Section B](https://llamakusi.com/tef-irn/guides/reussir-expression-orale-section-b) détaille comment construire une réponse claire sur ces thématiques.

*Exemple* : à l'oral du TEF IRN, un sujet comme « L'égalité femmes-hommes est-elle acquise en France ? » se traite avec la même méthode qu'une question de l'agent de préfecture.

> Entraînez-vous à voix haute sur des sujets de société, pas seulement sur le vocabulaire civique appris par cœur.

## Comment LlamaKusi vous aide

Chez LlamaKusi, l'objectif est simple : vous faire progresser plus vite grâce à un retour immédiat sur vos réponses. Le Coach IA Oral propose des mises en situation sur la laïcité et les valeurs républicaines, avec correction instantanée de votre structure et de votre vocabulaire. Pour un suivi complet et une correction détaillée de chaque passage, découvrez les [offres Premium LlamaKusi](/tef-irn/pricing), pensées pour les candidats visant la naturalisation en 2026. Vous progressez ainsi sur la langue et sur le fond en même temps. Notre [guide complet Motivation & Coaching IA](https://llamakusi.com/tef-irn/guides/motivation-bien-etre-coaching-tef-irn-guide-complet) rassemble toutes ces ressources selon votre profil.

## FAQ

**Dois-je donner mon opinion personnelle sur la religion pendant l'entretien ?**
Non. L'agent attend une compréhension du cadre légal, pas un avis personnel sur une religion en particulier.

**La laïcité interdit-elle de porter un signe religieux dans la rue ?**
Non. Elle encadre la neutralité de l'État et de ses agents, pas les convictions des citoyens dans l'espace public.

**Que se passe-t-il si je ne connais pas bien les valeurs de la République ?**
Une réponse incomplète peut entraîner un avis réservé, souvent suivi d'un ajournement plutôt que d'un rejet immédiat.

**Le TEF IRN teste-t-il directement la laïcité ?**
Pas par une question dédiée, mais l'Expression Orale peut porter sur des sujets de société proches de ceux abordés en préfecture.

**Combien de temps dure l'entretien d'assimilation ?**
En moyenne 20 à 50 minutes, avec une durée typique proche de 30 minutes selon la préfecture.
$CTA$ WHERE slug = 'tef-irn-et-laicite';

UPDATE public.guides SET content = $CTA$# Mindset TEF IRN : 3 Habitudes Mentales des Candidats qui Réussissent

Vous relisez vos fiches et une voix vous souffle que vous n'y arriverez jamais : ce n'est pas votre niveau qui est en cause, c'est votre mindset — et cela se travaille.

## Pourquoi le mental compte-t-il autant que le niveau de français au TEF IRN ?

À compétences égales, deux candidats peuvent obtenir des scores très différents selon leur état d'esprit face à l'épreuve.

Le TEF IRN évalue une **communication réelle**, pas un savoir théorique : [l'épreuve mesure la capacité à communiquer à l'oral avec un interlocuteur](https://www.lefrancaisdesaffaires.fr/candidat/test-evaluation-francais/tef-irn/presentation/), et le stress, l'auto-dévalorisation et la peur de l'erreur dégradent directement la fluidité et la clarté, même chez un candidat bien préparé. À l'inverse, un candidat convaincu qu'il peut progresser aborde chaque épreuve comme une situation à gérer plutôt qu'un jugement à subir. Ce n'est pas de la pensée magique : c'est un changement de posture mentale qui influence concrètement la performance à l'oral comme à l'écrit.

Un candidat se dit "je suis nul en français" avant l'Expression Orale ; un autre se dit "je ne maîtrise pas encore ce point, je vais m'entraîner dessus" — la différence de résultat le jour J vient souvent de là.

> Notez chaque soir une phrase que vous avez réussi à dire en français dans la journée, même simple. Ce carnet devient la preuve concrète de votre progression.

## Comment adopter un état d'esprit de croissance avant l'examen ?

Un état d'esprit de croissance consiste à croire que votre niveau de français **peut évoluer par l'effort**, et non qu'il est figé une fois pour toutes.

Ce concept, popularisé par la psychologue Carol Dweck, oppose la **mentalité fixe** ("je suis mauvais en langues, ça ne changera pas") à la **mentalité de croissance** ("je progresse à chaque session d'entraînement"). Concrètement, cela change la façon dont vous réagissez à une mauvaise note d'entraînement : la mentalité fixe y voit une confirmation d'échec, la mentalité de croissance y voit une information sur ce qu'il reste à travailler. Adopter cette posture demande de reformuler consciemment ses pensées négatives dès qu'elles apparaissent.

Après un examen blanc raté, dites-vous : "Je n'ai pas encore ce niveau" plutôt que "Je ne suis pas capable" — la nuance change tout dans la motivation qui suit.

> Reformulez systématiquement vos pensées d'échec en phrases commençant par "je n'ai pas encore", jamais "je ne peux pas".

## Comment utiliser la visualisation pour aborder l'oral avec confiance ?

Se visualiser réussir son épreuve orale avant l'examen entraîne le cerveau à associer cette situation au calme plutôt qu'à la panique.

La technique consiste à s'imaginer, dans un moment calme, en train de répondre à l'examinateur avec assurance : le lieu, sa propre voix posée, ses réponses claires. Plusieurs approches de préparation mentale utilisées pour les oraux de concours confirment que cet exercice renforce la confiance et réduit l'anxiété de performance en habituant l'esprit à une version réussie de la situation. Cinq minutes avant de dormir suffisent, à condition de faire l'exercice régulièrement dans les jours qui précèdent l'examen, pas seulement la veille.

Fermez les yeux, imaginez l'examinateur vous poser une question sur votre travail, et entendez-vous y répondre calmement en français, sans bafouiller.

> Associez cette visualisation à une respiration lente : quatre secondes d'inspiration, quatre secondes d'expiration, cela ancre physiquement le calme mental.

## Comment pratiquer l'auto-bienveillance face à ses erreurs de français ?

L'auto-bienveillance consiste à vous parler à vous-même comme vous parleriez à un ami qui apprend, plutôt qu'avec sévérité.

Beaucoup de candidats vivent chaque erreur de conjugaison ou d'accent comme une preuve d'incompétence, ce qui alimente un stress qui aggrave ensuite les vraies erreurs à l'oral. Se rappeler qu'apprendre une langue implique nécessairement des erreurs, à tous les niveaux, permet de rester concentré sur le contenu du message plutôt que sur la peur de mal parler. Cette bienveillance n'est pas de la complaisance : elle libère l'attention nécessaire pour progresser plus vite. Le guide sur [comment gagner confiance en français et vaincre le trac](https://llamakusi.com/tef-irn/guides/gagner-confiance-en-francais) détaille des exercices concrets pour ce travail sur soi.

Après une hésitation à l'oral, respirez et poursuivez votre phrase plutôt que de vous arrêter en pensant "j'ai tout raté".

> Après chaque session d'entraînement ratée, notez une chose que vous avez tout de même bien faite, même petite.

## Comment savoir si je progresse vraiment malgré l'impression de stagner ?

La progression en français est rarement linéaire : elle se mesure sur plusieurs semaines, pas d'une session d'entraînement à l'autre.

De nombreux candidats de niveau B1 sous-estiment leur niveau réel par manque de recul sur leurs propres progrès, un phénomène parfois qualifié de syndrome de l'imposteur linguistique. Comparer un enregistrement de soi datant d'un mois à un enregistrement récent est souvent plus fiable que le ressenti du moment, qui varie selon la fatigue ou le stress du jour. Le guide sur [pourquoi vous sous-estimez votre vrai niveau B1](https://llamakusi.com/tef-irn/guides/tef-irn-niveau-sous-estime) explique comment repérer objectivement ces progrès invisibles au quotidien.

Réécoutez un enregistrement de vous-même d'il y a trois semaines : la différence de fluidité est souvent plus nette que vous ne le pensiez.

## Comment LlamaKusi vous aide

Pas besoin d'attendre l'examen pour vous entraîner : le [Coach IA Oral](/tef-irn/oral) est inclus dans votre abonnement LlamaKusi, dans un cadre sans jugement qui laisse justement la place à ce travail sur la confiance. Chaque session vous montre une progression mesurable, ce qui nourrit concrètement un état d'esprit de croissance. Chaque profil est différent : les [formules Premium LlamaKusi](/tef-irn/pricing) s'adaptent à votre niveau et à votre échéance pour un accompagnement plus structuré. Pour structurer l'ensemble de votre préparation, notre [guide complet sur la méthode de révision](https://llamakusi.com/tef-irn/guides/methode-revision-tef-irn-guide-complet) rassemble tous nos conseils d'organisation.

## FAQ

**Le mindset peut-il vraiment faire gagner des points au TEF IRN ?**
Oui, indirectement : moins de stress signifie plus de fluidité et de clarté à l'oral comme à l'écrit, ce qui améliore la performance réelle mesurée par les examinateurs, [dont les grilles d'évaluation standardisées prennent en compte des critères comme la fluidité, le lexique et la grammaire](https://www.lefrancaisdesaffaires.fr/candidat/test-evaluation-francais/tef-irn/resultats/).

**Combien de temps faut-il pour changer son état d'esprit ?**
Quelques semaines de pratique régulière suffisent généralement à ressentir moins d'anxiété, à condition de répéter les exercices plutôt que de les faire une seule fois.

**Que faire si le stress revient le jour de l'examen malgré la préparation mentale ?**
C'est normal : concentrez-vous sur la respiration lente et sur la première question posée, sans anticiper la suite de l'épreuve.

**Faut-il être naturellement optimiste pour appliquer ces habitudes ?**
Non, l'état d'esprit de croissance se construit par la pratique, pas par un trait de personnalité inné.
$CTA$ WHERE slug = 'tef-irn-mindset-vainqueur';

UPDATE public.guides SET content = $CTA$# Naturalisation 2026 : Pourquoi le TEF IRN Ne Suffit Pas (3 Oublis)

Vous avez décroché votre **B2** au TEF IRN et pensez déjà tenir votre naturalisation. En réalité, l'examen civique, l'entretien et vos revenus comptent tout autant que la langue.

## Le TEF IRN niveau B2 suffit-il à lui seul pour la naturalisation en 2026 ?

Non, réussir le TEF IRN **B2** valide uniquement votre niveau de français, pas l'ensemble de votre dossier de naturalisation.

Depuis le **1er janvier 2026**, [le niveau B2 à l'oral et à l'écrit est devenu obligatoire pour toute demande de naturalisation par décret](https://www.service-public.fr/particuliers/vosdroits/F11926), remplaçant l'ancien niveau B1. Mais ce certificat linguistique n'est qu'une pièce parmi d'autres : le dossier complet exige aussi la réussite de l'examen civique national et la preuve d'une stabilité financière suffisante.

Exemple concret : « Vous avez votre TEF IRN B2 ? » demande l'agent de préfecture. « Oui, très bien réussi. » « Parfait, passons maintenant à l'examen civique et à votre situation professionnelle. »

> Considérez le TEF IRN comme la première étape d'un parcours en trois volets, pas comme la ligne d'arrivée.

## Qu'est-ce que l'examen civique NAT change concrètement dans le dossier de naturalisation ?

Depuis janvier 2026, l'examen civique NAT est une épreuve obligatoire distincte de l'entretien, avec [40 questions à choix multiples et un score minimum de **32/40 (80 %)**](https://www.service-public.gouv.fr/particuliers/actualites/A18713) à obtenir.

Ce test QCM de 45 minutes maximum se déroule sur tablette numérique dans un centre agréé et évalue vos connaissances des valeurs, de l'histoire et des institutions françaises. L'attestation de réussite devient une pièce obligatoire du dossier, en complément de l'entretien en préfecture qui, lui, reste maintenu.

Exemple concret : une question type peut porter sur « Quelles sont les valeurs inscrites dans la devise de la République ? », avec quatre choix de réponse proposés.

> Révisez le Livret du citoyen dès le dépôt du dossier : l'examen civique doit être réussi avant l'entretien, pas après.

## Pourquoi l'entretien en préfecture peut-il recaler un candidat malgré un excellent niveau de français ?

Parce que l'entretien évalue votre assimilation réelle aux valeurs républicaines, pas seulement votre capacité à vous exprimer en français.

Mené par un agent assermenté pendant 20 à 30 minutes, l'entretien vérifie votre parcours personnel et professionnel, votre adhésion aux principes de liberté, égalité, fraternité et laïcité, ainsi que votre motivation. Un candidat qui maîtrise parfaitement le français mais peine à expliquer ces valeurs avec ses propres mots peut voir son dossier ajourné. Notre [guide complet sur la naturalisation française en 2026](https://llamakusi.com/tef-irn/guides/preparer-naturalisation-francaise-2026) détaille l'ensemble des pièces attendues pour ce rendez-vous.

Exemple concret : « Que signifie la laïcité pour vous ? » demande l'agent. Une réponse apprise par cœur inquiète souvent davantage qu'une réponse simple et sincère.

> Entraînez-vous à répondre à voix haute, sans notes, plutôt qu'à mémoriser des phrases toutes faites.

## La stabilité financière peut-elle vraiment bloquer une naturalisation en 2026 ?

Oui : depuis le durcissement de mai 2025, l'insertion professionnelle et la régularité des revenus sont examinées avec une attention accrue sur les cinq dernières années.

Les préfectures vérifient que vos ressources proviennent majoritairement d'une activité stable plutôt que d'aides sociales, et que vos déclarations fiscales sont cohérentes. Aucun seuil de salaire n'est fixé par la loi, mais un parcours professionnel irrégulier ou des dettes fiscales peuvent motiver un ajournement — un des motifs que détaille notre guide sur les [erreurs qui font échouer un dossier de naturalisation](https://llamakusi.com/tef-irn/guides/refus-dossier-prefecture-francais).

Exemple concret : un candidat en CDI depuis trois ans avec des revenus modestes mais réguliers présente souvent un dossier plus solide qu'un candidat aux revenus élevés mais irréguliers.

> Rassemblez avis d'imposition, fiches de paie et contrat de travail sur cinq ans avant de déposer votre dossier.

## Comment LlamaKusi vous aide

Comment s'entraîner efficacement sans y passer des heures chaque jour ? LlamaKusi vous accompagne sur la partie qui reste sous votre contrôle direct : votre niveau de français. La meilleure façon de progresser reste la pratique orale répétée : essayez le [Coach IA Oral](/tef-irn/oral) avec votre abonnement pour muscler votre expression avant l'examen. Pour un accompagnement plus poussé jusqu'au niveau B2, découvrez les [offres Premium LlamaKusi](/tef-irn/pricing). Retrouvez toutes les étapes de votre dossier dans le [guide complet Naturalisation TEF IRN 2026](https://llamakusi.com/tef-irn/guides/naturalisation-demarches-tef-irn-guide-complet).

## FAQ

**Le TEF IRN et l'examen civique sont-ils la même chose ?**
Non. Le TEF IRN évalue votre niveau de français, tandis que l'examen civique NAT teste vos connaissances des valeurs et institutions françaises. Ce sont deux épreuves distinctes et toutes deux obligatoires.

**Combien de temps dure l'entretien de naturalisation en 2026 ?**
Il dure généralement entre 20 et 30 minutes et se déroule entièrement en français avec un agent assermenté de préfecture.

**Faut-il un salaire minimum pour être naturalisé ?**
Aucun seuil légal n'existe. Les préfectures examinent surtout la stabilité et la régularité de vos revenus sur plusieurs années, pas leur montant exact.

**Peut-on repasser l'examen civique en cas d'échec ?**
Oui, il est possible de se réinscrire dans un centre agréé. Cela retarde toutefois le dépôt du dossier complet, mieux vaut donc bien préparer ce test dès le départ.

**Le niveau B2 est-il obligatoire pour toutes les démarches liées au TEF IRN ?**
Non. Il est obligatoire depuis janvier 2026 pour la naturalisation par décret, mais le niveau B1 suffit encore pour la carte de résident de longue durée.
$CTA$ WHERE slug = 'tef-irn-ne-suffit-pas';

UPDATE public.guides SET content = $CTA$# Syndrome de l'Imposteur TEF IRN : Pourquoi Vous Sous-estimez Votre Niveau

Vous hésitez à vous inscrire au TEF IRN car vous pensez ne pas être prêt. Bonne nouvelle : votre niveau réel dépasse presque toujours votre perception sous stress.

## Pourquoi ai-je l'impression d'avoir un niveau plus faible que la réalité ?

Ce décalage vient rarement d'un vrai manque de compétences. Il vient d'une évaluation faite dans les pires conditions possibles : le stress.

Votre cerveau associe la langue française à des situations d'apprentissage scolaire, où l'erreur était sanctionnée. Face à un **examen officiel**, ce réflexe ressurgit et vous fait douter de choses que vous maîtrisez pourtant au quotidien. Vous parlez français au travail, avec vos voisins, dans les démarches administratives, mais vous ne comptabilisez pas ces réussites comme des preuves de niveau.

Par exemple, un candidat qui négocie déjà un rendez-vous chez le médecin en français a, sans le savoir, un **niveau B1 fonctionnel** à l'oral.

> Notez chaque situation en français gérée sans effort cette semaine : cette liste devient une preuve concrète contre votre auto-dévalorisation.

## Quelle différence entre "savoir" le français et "savoir-faire" à l'examen ?

Le "savoir" désigne vos connaissances : grammaire, vocabulaire, conjugaison. Le "savoir-faire" désigne votre capacité à mobiliser ces connaissances en temps réel, sous contrainte de temps.

Le TEF IRN évalue en priorité le savoir-faire, pas le savoir théorique. Un candidat peut connaître parfaitement une règle de grammaire et échouer à l'appliquer à l'oral, simplement par manque d'entraînement dans des conditions proches de l'examen. Ce n'est pas un problème de niveau, c'est un problème d'**entraînement en situation réelle**.

À l'oral, un examinateur pose : « Que pensez-vous du télétravail ? » Le candidat qui bloque connaît souvent le vocabulaire, mais manque de réflexe pour structurer sa réponse vite.

> Entraînez-vous à répondre à voix haute en 30 secondes, chronomètre en main, plutôt qu'à réviser des listes de vocabulaire en silence.

## Pourquoi le stress fait-il chuter mon score alors que je maîtrise la langue ?

Le stress mobilise l'énergie mentale vers la gestion de l'anxiété, au détriment de la réflexion linguistique. Résultat : votre score le jour J ne reflète pas votre niveau réel, mais votre niveau sous pression.

C'est un phénomène documenté en psychologie de l'apprentissage : plus l'enjeu perçu est élevé, plus l'accès aux connaissances déjà acquises devient difficile. Ce mécanisme touche aussi bien les débutants que les candidats déjà solides en français. Il explique pourquoi certains candidats obtiennent, en conditions d'entraînement détendues, un score nettement supérieur à leur résultat officiel.

Si cette épreuve vous angoisse, le [Coach IA Oral](/tef-irn/oral) permet de s'entraîner en conditions réelles, avec votre abonnement.

> Simulez l'examen dans des conditions proches du réel plusieurs fois avant la date officielle, pour désensibiliser le stress.

## Comment reconnaître les signes du syndrome de l'imposteur linguistique ?

Le syndrome de l'imposteur se manifeste par un décalage persistant entre vos compétences réelles et votre perception, même face à des preuves de réussite.

Concrètement, vous attribuez vos réussites en français à la chance ou à la gentillesse de votre interlocuteur, jamais à votre compétence. Vous évitez de vous inscrire au TEF IRN par peur d'un échec qui confirmerait vos doutes, alors même que votre entourage vous complimente sur votre français. Ce phénomène est différent d'un simple manque de confiance ponctuel : il persiste malgré les compliments et les réussites objectives.

Une candidate qui parle couramment avec ses collègues français continue de dire « je ne suis pas prêt » avant chaque test blanc.

> Demandez à un proche francophone d'évaluer honnêtement votre niveau : un regard extérieur corrige souvent l'auto-évaluation biaisée.

## Quel niveau B1 est réellement exigé pour ma démarche en 2026 ?

Depuis le **1er janvier 2026**, les exigences de niveau varient selon votre démarche : A2 pour la carte de séjour pluriannuelle, B1 pour la carte de résident, [B2 pour la naturalisation](https://www.service-public.fr/particuliers/vosdroits/F11926).

Cette évolution découle de la loi n°2024-42 du 26 janvier 2024 et des décrets n°2025-647 et 2025-648 du 15 juillet 2025. Beaucoup de candidats confondent encore les seuils : viser un B1 suffisait pour la naturalisation avant cette réforme, ce n'est plus le cas aujourd'hui. Le [TEF IRN](/tef-irn/oral), délivré par la CCI Paris IDF, et le [TCF IRN, délivré par France Éducation International](https://www.france-education-international.fr/test/tcf-irn), restent tous deux acceptés par les préfectures pour ces démarches.

Un candidat visant uniquement la carte de résident doit viser un score B1, pas B2.

> Vérifiez la démarche exacte visée (carte de résident, naturalisation, carte pluriannuelle) avant de vous fixer un objectif de score.

## Comment LlamaKusi vous aide

LlamaKusi transforme cette préparation en méthode claire plutôt qu'en révisions dans le vide. Le test de positionnement objective votre niveau réel, loin du stress de l'examen officiel. Chaque profil est différent : les [formules Premium LlamaKusi](/tef-irn/pricing) s'adaptent à votre niveau et à votre échéance. Pour aller plus loin sur la gestion du trac le jour J, consultez aussi notre guide pour [vaincre le trac à l'oral du TEF IRN](https://llamakusi.com/tef-irn/guides/gagner-confiance-en-francais). Si vous cherchez à organiser votre planning plus largement, consultez notre [guide complet Méthode de Révision](https://llamakusi.com/tef-irn/guides/methode-revision-tef-irn-guide-complet).

## FAQ

**Comment savoir si mon niveau B1 est suffisant sans passer l'examen ?**
Un test de positionnement gratuit donne une estimation fiable, sans le stress d'un examen officiel noté.

**Le syndrome de l'imposteur peut-il faire baisser mon score réel ?**
Oui, indirectement : il pousse à repousser l'inscription et réduit le temps d'entraînement en conditions réelles.

**Dois-je viser B1 ou B2 pour ma naturalisation en 2026 ?**
Depuis janvier 2026, la naturalisation exige un niveau B2, pas B1, contrairement à la carte de résident.

**Le TEF IRN est-il plus difficile que le TCF IRN pour un niveau B1 ?**
Les deux tests évaluent les mêmes compétences ; le choix dépend surtout du centre d'examen disponible près de chez vous.

**Combien de temps faut-il pour corriger cette sous-estimation de mon niveau ?**
Quelques semaines d'entraînement en conditions réelles suffisent généralement à aligner perception et niveau réel. Notre [guide complet du TEF IRN](https://llamakusi.com/tef-irn/guides/tout-comprendre-tef-irn) détaille le format complet de l'examen.
